"use strict";
const $=id=>document.getElementById(id), esc=(v="")=>String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]), money=n=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(n);
const products=[{id:"moletom",name:"Moletom",price:159.90,image:"assets/moletom.png",sizes:["P","M","G","GG"]},{id:"bone",name:"Boné",price:69.90,image:"assets/bone.png",sizes:[]},{id:"short-feminino",name:"Short feminino",price:59.90,image:"assets/short-feminino.png",sizes:["P","M","G","GG"]},{id:"camisa-feminina",name:"Camisa feminina",price:69.90,image:"assets/camisa-feminina.png",sizes:["P","M","G","GG"]},{id:"chaveiro",name:"Chaveiro",price:12.90,image:"assets/chaveiro.png",sizes:[]}];
const events=[{date:"MAR · DATA A DEFINIR",title:"Festa de abertura",detail:"Encontro de início de semestre.",price:25},{date:"ABR · PREVISÃO",title:"Copa Inteli + Copa Vôlei",detail:"Proposta de interclasse com esportes de quadra e vôlei de areia."},{date:"MAI · PREVISÃO",title:"Campeonato de E-sports",detail:"Proposta de torneio com equipes de diferentes faculdades."}];
let cart=[],timer,submit,publicBenefits=[],publicContent=[],currentTicketLot=null,team={user:null,records:[],suggestions:[],areas:[],categories:[],view:"archive",filters:{year:"",area:"",category:"",search:""}};
const inTeam=()=>location.hash==="#equipe";
function notify(m){$("toast").textContent=m;clearTimeout(timer);timer=setTimeout(()=>$("toast").textContent="",4500)}
async function api(path,opts={}){const r=await fetch(path,{credentials:"same-origin",headers:{"Content-Type":"application/json",...(opts.headers||{})},...opts});const data=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(data.error||"Não foi possível concluir a operação.");e.code=data.code;throw e}return data}
function section(id,kicker,title,body){return '<section class="shell section" id="'+id+'"><div class="eyebrow">'+kicker+'</div><h2>'+title+'</h2>'+body+'</section>'}
function student(){
  $("topnav").innerHTML='<a href="#ingressos">Ingressos</a><a href="#shop">Shop</a><a href="#calendario">Calendário</a><a href="#parcerias">Parcerias</a><a href="#duvidas">Dúvidas</a>';
  $("app").innerHTML='<section class="hero" id="inicio"><div class="shell hero-layout"><div><div class="eyebrow">Atlética do Inteli</div><h1>Atlética<br><em>Tantera.</em></h1><p>Ingressos, produtos e os próximos encontros da comunidade do Inteli.</p><div class="actions"><a class="primary" href="#ingressos">Ver ingressos ↗</a><a class="secondary" href="#calendario">Explorar calendário</a></div></div><img class="hero-emblem" src="emblema-tantera.jpg" alt="Emblema da Atlética Tantera" width="1080" height="1080"></div></section><div class="quick"><div class="shell"><a href="#ingressos">Ingressos ↗</a><a href="#shop">Shop Tantera ↗</a><a href="#calendario">Calendário ↗</a></div></div>'+section("ingressos","Eventos","Ingressos",'<div class="card"><span class="date">VENDA SIMULADA</span><h3>'+events[0].title+'</h3><p>'+events[0].detail+'</p><div class="price">'+money(events[0].price)+'</div><button class="primary" data-buy="ticket">Comprar ingresso</button></div>')+shop()+section("calendario","Agenda ilustrativa","Próximos eventos",'<div class="grid">'+events.map(e=>'<article class="card"><span class="date">'+e.date+'</span><h3>'+e.title+'</h3><p class="muted">'+e.detail+'</p></article>').join("")+'</div>')+section("parcerias","Captação","Parcerias e benefícios",'<p class="muted">Vitrine de exemplo para parcerias divulgadas pela Tantera.</p>')+section("duvidas","Perguntas frequentes","Tire suas dúvidas",'<details><summary>Como compro um ingresso?</summary><p>Na seção Ingressos, selecione o evento e a quantidade para simular a compra.</p></details><details><summary>As datas estão confirmadas?</summary><p>O calendário mostra previsões ilustrativas para a apresentação.</p></details>');
}
function shop(){return section("shop","Produtos","Shop Tantera",'<div class="grid shop-grid">'+products.map(p=>'<article class="card product-card"><img class="product-photo" src="'+p.image+'" alt="'+esc(p.name)+' Tantera"><h3>'+esc(p.name)+'</h3><div class="price">'+money(p.price)+'</div><button class="secondary" data-buy="'+p.id+'">'+(p.sizes.length?"Escolher tamanho":"Adicionar à sacola")+'</button></article>').join("")+'</div><button class="primary" style="margin-top:16px" data-cart>Ver sacola ('+cart.length+')</button>')}
function loginView(message=""){$("topnav").innerHTML="";$('app').innerHTML='<div class="shell auth-page"><div class="auth-card"><div class="eyebrow">Área restrita</div><h1>Login da equipe</h1><p class="muted">Entre com sua conta individual para acessar o Acervo e as ferramentas da equipe.</p>'+(message?'<p class="auth-error">'+esc(message)+'</p>':'')+'<form id="login-form"><label class="field">E-mail<input required type="email" name="email" autocomplete="username"></label><label class="field">Senha<input required type="password" name="password" autocomplete="current-password"></label><button class="primary" type="submit">Entrar</button></form></div></div>'}
function changePasswordView(){ $("topnav").innerHTML="";$('app').innerHTML='<div class="shell auth-page"><div class="auth-card"><div class="eyebrow">Primeiro acesso</div><h1>Troque sua senha</h1><p class="muted">A senha temporária precisa ser substituída antes de acessar os dados da equipe.</p><form id="password-form"><label class="field">Nova senha<input required minlength="10" type="password" name="password" autocomplete="new-password"></label><label class="field">Confirmar nova senha<input required minlength="10" type="password" name="confirm" autocomplete="new-password"></label><button class="primary" type="submit">Salvar nova senha</button></form></div></div>'}
async function startTeam(){if(!team.user){loginView();try{const r=await api("/api/auth/me");team.user=r.user;if(team.user?.mustChangePassword)return changePasswordView();if(team.user)await loadTeam()}catch{}}else if(team.user.mustChangePassword)changePasswordView();else await loadTeam()}
async function loadTeam(){try{const r=await api("/api/team/records");Object.assign(team,r);renderTeam()}catch(e){notify(e.message);if(e.code==="PASSWORD_CHANGE_REQUIRED")changePasswordView()}}
function teamNav(){return '<nav class="tabs" aria-label="Navegação da equipe">'+team.areas.map(a=>'<button data-area="'+esc(a)+'">'+esc(a)+'</button>').join("")+'<button class="archive-tab '+(team.view==="archive"?'active':'')+'" data-view="archive">▣ Acervo da Tantera</button>'+(team.user.role==="presidente"?'<button class="archive-tab '+(team.view==="members"?'active':'')+'" data-view="members">⚙ Gerenciar equipe</button>':'')+'</nav>'}
function renderTeam(){ $("topnav").innerHTML='<span class="team-user">'+esc(team.user.name)+' · '+esc(team.user.role)+'</span><button class="switch" data-logout>Sair</button>';if(team.view==="members")return membersView();if(team.view==="archive")return archiveView();areaView(team.view)}
function teamShell(content,title="Acervo da Tantera",subtitle="Registros e sugestões compartilhados com a equipe."){return '<div class="shell dash"><div class="dash-top"><div><div class="eyebrow">Área da equipe · '+esc(team.user.role)+'</div><h1>'+title+'</h1><p class="muted">'+subtitle+'</p></div><div class="role"><strong>'+esc(team.user.name)+'</strong><small>'+esc(team.user.email)+'</small></div></div><div class="layout">'+teamNav()+'<section class="panel">'+content+'</section></div></div>'}
function archiveView(){const f=team.filters,visible=team.records.filter(r=>(r.status==="Aprovada"||r.area===team.user.area||team.user.role==="presidente")&&(!f.year||r.year===f.year)&&(!f.area||r.area===f.area)&&(!f.category||r.category===f.category)&&(!f.search||[r.title,r.description,r.keywords].join(" ").toLowerCase().includes(f.search.toLowerCase()))),pending=team.suggestions||[];const content='<div class="panel-head"><div><h2>Acervo da Tantera</h2><p class="muted">'+(team.user.role==="integrante"?"Consulte materiais aprovados e envie sugestões.":"Você pode administrar os materiais permitidos pela sua função.")+'</p></div><button class="primary" data-suggest>Sugerir material</button></div><div class="filters"><label>Buscar por título ou palavra-chave<input id="archive-search" value="'+esc(f.search)+'" placeholder="Ex.: arbitragem, mascote..."></label><label>Ano da gestão<select id="archive-year"><option value="">Todos os anos</option>'+[...new Set(team.records.map(r=>r.year))].sort().reverse().map(y=>'<option value="'+esc(y)+'" '+(f.year===y?"selected":"")+'>'+esc(y)+'</option>').join("")+'</select></label><label>Área responsável<select id="archive-area"><option value="">Todas as áreas</option>'+team.areas.map(a=>'<option value="'+esc(a)+'" '+(f.area===a?"selected":"")+'>'+esc(a)+'</option>').join("")+'</select></label><label>Categoria<select id="archive-category"><option value="">Todas as categorias</option>'+team.categories.map(c=>'<option value="'+esc(c)+'" '+(f.category===c?"selected":"")+'>'+esc(c)+'</option>').join("")+'</select></label></div><p class="results-count">'+visible.length+' registro(s) encontrado(s)</p><div class="grid archive-grid">'+(visible.length?visible.map(r=>'<article class="card archive-card"><div class="archive-meta"><span class="date">GESTÃO '+esc(r.year)+'</span>'+(r.example?'<span class="pill">Exemplo</span>':'')+'</div><h3>'+esc(r.title)+'</h3><p class="muted">'+esc(r.category)+' · '+esc(r.area)+'</p><button class="secondary" data-detail="'+r.id+'">Ver detalhes</button></article>').join(""):'<div class="empty card"><h3>Nenhum registro encontrado</h3><p class="muted">Tente remover um filtro ou outra palavra-chave.</p></div>')+'</div>'+(pending.length?'<div class="queue"><h3>Sugestões pendentes da sua área</h3>'+pending.map(s=>'<article class="card"><span class="pill">Pendente</span><h3>'+esc(s.title)+'</h3><p>'+esc(s.description)+'</p><div class="actions"><button class="primary" data-approve="'+s.id+'">Aprovar</button><button class="secondary" data-reject="'+s.id+'">Recusar</button></div></article>').join("")+'</div>':'');$("app").innerHTML=teamShell(content)}
function areaView(area){const records=team.records.filter(r=>r.area===area&&r.status==="Aprovada");const content='<div class="panel-head"><div><h2>'+esc(area)+'</h2><p class="muted">Registros aprovados da área.</p></div><button class="primary" data-suggest>Enviar sugestão</button></div><div class="grid">'+records.map(r=>'<article class="card"><h3>'+esc(r.title)+'</h3><p class="muted">'+esc(r.description)+'</p><button class="secondary" data-detail="'+r.id+'">Ver detalhes</button></article>').join("")+'</div>';$("app").innerHTML=teamShell(content,area,"Consulta dos registros aprovados desta área.")}
function membersView(){api("/api/team/members").then(({users})=>{$("app").innerHTML=teamShell('<div class="panel-head"><div><h2>Gerenciar equipe</h2><p class="muted">Cadastre, redefina e desative contas da equipe.</p></div><button class="primary" data-member-new>Cadastrar pessoa</button></div><div class="grid members-grid">'+users.map(u=>'<article class="card member-card"><span class="pill '+(u.active?'approved':'rejected')+'">'+(u.active?'Ativa':'Desativada')+'</span><h3>'+esc(u.name)+'</h3><p>'+esc(u.email)+'</p><p class="muted">'+esc(u.role)+' · '+esc(u.area)+'</p>'+(u.mustChangePassword?'<p class="muted">Aguardando troca da senha</p>':'')+'<div class="actions"><button class="secondary" data-reset="'+u.id+'">Redefinir acesso</button><button class="secondary" data-toggle="'+u.id+'">'+(u.active?'Desativar':'Reativar')+'</button></div></article>').join("")+'</div>',"Gerenciar equipe","Controle administrativo das contas da equipe.")}).catch(e=>notify(e.message))}
function openModal(title,fields,label,callback){$("fields").innerHTML='<h3 id="modal-title">'+title+'</h3>'+fields;$("confirm").textContent=label;submit=callback;$("modal").showModal()}
function suggestModal(){openModal("Sugerir material",'<label class="field">Título<input required name="title" maxlength="120"></label><div class="form-row"><label class="field">Ano<input required name="year" value="2025" pattern="[0-9]{4}"></label><label class="field">Área<select required name="area">'+team.areas.map(a=>'<option>'+esc(a)+'</option>').join("")+'</select></label></div><label class="field">Categoria<select required name="category">'+team.categories.map(c=>'<option>'+esc(c)+'</option>').join("")+'</select></label><label class="field">Descrição<textarea required name="description" maxlength="700"></textarea></label><label class="field">Palavras-chave<input name="keywords"></label><label class="field">Link do material<input type="url" name="url"></label>',"Enviar para aprovação",async d=>{const b={title:d.get("title"),year:d.get("year"),area:d.get("area"),category:d.get("category"),description:d.get("description"),keywords:d.get("keywords"),materials:d.get("url")?[{name:"Material online",url:d.get("url")}]:[]};try{await api("/api/team/suggestions",{method:"POST",body:JSON.stringify(b)});$("modal").close();await loadTeam();notify("Sugestão enviada para aprovação.")}catch(e){notify(e.message)}return false})}
function memberModal(){openModal("Cadastrar pessoa",'<label class="field">Nome<input required name="name"></label><label class="field">E-mail<input required type="email" name="email"></label><div class="form-row"><label class="field">Cargo<select name="role"><option value="diretor">Diretor</option><option value="integrante">Integrante</option></select></label><label class="field">Área<select name="area">'+team.areas.map(a=>'<option>'+esc(a)+'</option>').join("")+'</select></label></div><label class="field">Senha temporária<input required minlength="10" name="temporaryPassword" type="password"><small>Mínimo de 10 caracteres; a troca será exigida no primeiro acesso.</small></label>',"Cadastrar",async d=>{try{await api("/api/team/members",{method:"POST",body:JSON.stringify(Object.fromEntries(d))});$("modal").close();membersView();notify("Conta cadastrada. A troca de senha será exigida no primeiro acesso.")}catch(e){notify(e.message)}return false})}
function detail(id){const r=team.records.find(x=>x.id===id);if(!r)return;openModal(r.title,'<div class="detail-head"><span class="date">GESTÃO '+esc(r.year)+'</span><span class="pill">'+esc(r.category)+'</span></div><p><strong>Área responsável:</strong> '+esc(r.area)+'</p><p>'+esc(r.description)+'</p><h4>Materiais disponíveis</h4><ul>'+(r.materials?.length?r.materials.map(m=>'<li><a target="_blank" rel="noreferrer" href="'+esc(m.url||"#")+'">'+esc(m.name||"Abrir material")+' ↗</a></li>').join(""):'<li>Nenhum material anexado.</li>')+'</ul>',"Fechar",()=>{})}
function buy(id){const p=products.find(x=>x.id===id);if(!p)return;if(!p.sizes.length){cart.push({...p,size:"Único"});render();notify("Produto adicionado à sacola.");return}openModal(p.name,'<p>'+money(p.price)+'</p><label class="field">Tamanho<select name="size">'+p.sizes.map(s=>'<option>'+s+'</option>').join("")+'</select></label>',"Adicionar à sacola",d=>{cart.push({...p,size:d.get("size")});$("modal").close();render();notify("Produto adicionado à sacola.")})}
function cartModal(){if(!cart.length)return notify("Sua sacola está vazia.");openModal("Sacola Tantera",'<ul>'+cart.map(p=>'<li>'+esc(p.name)+' · '+p.size+' · '+money(p.price)+'</li>').join("")+'</ul><p class="price">Total '+money(cart.reduce((s,p)=>s+p.price,0))+'</p>',"Simular pedido",()=>{cart=[];$("modal").close();render();notify("Pedido simulado com sucesso.")})}
$("app").addEventListener("click",async e=>{const b=e.target.closest("button");if(!b)return;const d=b.dataset;if(d.buy)buy(d.buy);else if("cart" in d)cartModal();else if(d.view){team.view=d.view;renderTeam()}else if(d.area){team.view=d.area;renderTeam()}else if(d.suggest!==undefined)suggestModal();else if(d.detail)detail(d.detail);else if(d.approve||d.reject){try{await api('/api/team/suggestions/'+(d.approve||d.reject)+'/'+(d.approve?'approve':'reject'),{method:'POST'});await loadTeam();notify(d.approve?'Sugestão aprovada.':'Sugestão recusada.')}catch(err){notify(err.message)}}else if(d.memberNew!==undefined)memberModal();else if(d.reset||d.toggle){const id=d.reset||d.toggle;if(d.reset){openModal("Redefinir acesso",'<label class="field">Nova senha temporária<input required minlength="10" name="password" type="password"></label>',"Redefinir",async data=>{try{await api('/api/team/members/'+id,{method:'PATCH',body:JSON.stringify({temporaryPassword:data.get('password')})});$("modal").close();membersView();notify("Acesso redefinido.")}catch(err){notify(err.message)}return false})}else{try{await api('/api/team/members/'+id,{method:'PATCH',body:JSON.stringify({active:d.toggle?false:true})});membersView()}catch(err){notify(err.message)}}}});$("app").addEventListener("change",e=>{if(e.target.id==="archive-year"||e.target.id==="archive-area"||e.target.id==="archive-category"){team.filters={...team.filters,year:$("archive-year").value,area:$("archive-area").value,category:$("archive-category").value};renderTeam()}});$("app").addEventListener("input",e=>{if(e.target.id==="archive-search"){team.filters.search=e.target.value;renderTeam();$("archive-search").focus()}});
$("app").addEventListener("submit",async e=>{e.preventDefault();const f=e.target;if(f.id==="login-form"){try{const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});team.user=r.user;if(team.user.mustChangePassword)changePasswordView();else await loadTeam()}catch(err){loginView(err.message)}}else if(f.id==="password-form"){const d=Object.fromEntries(new FormData(f));if(d.password!==d.confirm)return notify("As senhas não conferem.");try{const r=await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({password:d.password})});team.user=r.user;await loadTeam();notify("Senha atualizada.")}catch(err){notify(err.message)}}});$("switch").onclick=()=>{location.hash=inTeam()?"inicio":"equipe"};$("close").onclick=()=>$("modal").close();$("form").onsubmit=e=>{e.preventDefault();if(submit)submit(new FormData(e.currentTarget))};document.addEventListener("click",async e=>{if(!e.target.closest('[data-logout]'))return;await api('/api/auth/logout',{method:'POST'}).catch(()=>{});team.user=null;location.hash='inicio'});
let previous=inTeam();function render(){if(inTeam()){if(team.user)renderTeam();else startTeam()}else student();$("switch").textContent=inTeam()?"← Área dos alunos":"Área da equipe →"}window.addEventListener("hashchange",()=>{if(previous!==inTeam()){previous=inTeam();render();if(inTeam())scrollTo(0,0)}requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView())});render();

/* Direct administration is intentionally backed by server routes; the client never decides permission. */
function directRecordModal(editId="") { const old=editId?team.records.find(r=>r.id===editId):null; const editableArea=team.user.role==="presidente"?team.areas:(team.user.area?[team.user.area]:[]); openModal(old?"Editar registro":"Novo registro",'<label class="field">Título<input required name="title" value="'+esc(old?.title||"")+'"></label><div class="form-row"><label class="field">Ano<input required name="year" pattern="[0-9]{4}" value="'+esc(old?.year||"2025")+'"></label><label class="field">Área<select required name="area">'+editableArea.map(a=>'<option '+((old?.area||team.user.area)===a?'selected':'')+'>'+esc(a)+'</option>').join("")+'</select></label></div><label class="field">Categoria<select required name="category">'+team.categories.map(c=>'<option '+(old?.category===c?'selected':'')+'>'+esc(c)+'</option>').join("")+'</select></label><label class="field">Descrição<textarea required name="description">'+esc(old?.description||"")+'</textarea></label><label class="field">Palavras-chave<input name="keywords" value="'+esc(old?.keywords||"")+'"></label>',old?"Salvar alterações":"Publicar registro",async d=>{const b=Object.fromEntries(d);try{await api(old?'/api/team/records/'+old.id:'/api/team/records',{method:old?'PATCH':'POST',body:JSON.stringify(b)});$("modal").close();await loadTeam();notify(old?"Registro atualizado.":"Registro publicado.")}catch(e){notify(e.message)}return false}) }
function archiveView(){const f=team.filters,visible=team.records.filter(r=>(r.status==="Aprovada"||r.area===team.user.area||team.user.role==="presidente")&&(!f.year||r.year===f.year)&&(!f.area||r.area===f.area)&&(!f.category||r.category===f.category)&&(!f.search||[r.title,r.description,r.keywords].join(" ").toLowerCase().includes(f.search.toLowerCase()))),pending=team.suggestions||[],direct=team.user.role!=="integrante";const content='<div class="panel-head"><div><h2>Acervo da Tantera</h2><p class="muted">'+(team.user.role==="integrante"?"Consulte materiais aprovados e envie sugestões.":"Administre materiais permitidos pela sua função.")+'</p></div><div class="actions"><button class="primary" data-suggest>Sugerir material</button>'+(direct?'<button class="secondary" data-direct-new>Novo registro</button>':'')+'</div></div><div class="filters"><label>Buscar por título ou palavra-chave<input id="archive-search" value="'+esc(f.search)+'" placeholder="Ex.: arbitragem, mascote..."></label><label>Ano da gestão<select id="archive-year"><option value="">Todos os anos</option>'+[...new Set(team.records.map(r=>r.year))].sort().reverse().map(y=>'<option value="'+esc(y)+'" '+(f.year===y?"selected":"")+'>'+esc(y)+'</option>').join("")+'</select></label><label>Área responsável<select id="archive-area"><option value="">Todas as áreas</option>'+team.areas.map(a=>'<option value="'+esc(a)+'" '+(f.area===a?"selected":"")+'>'+esc(a)+'</option>').join("")+'</select></label><label>Categoria<select id="archive-category"><option value="">Todas as categorias</option>'+team.categories.map(c=>'<option value="'+esc(c)+'" '+(f.category===c?"selected":"")+'>'+esc(c)+'</option>').join("")+'</select></label></div><p class="results-count">'+visible.length+' registro(s) encontrado(s)</p><div class="grid archive-grid">'+(visible.length?visible.map(r=>'<article class="card archive-card"><div class="archive-meta"><span class="date">GESTÃO '+esc(r.year)+'</span>'+(r.example?'<span class="pill">Exemplo</span>':'')+'</div><h3>'+esc(r.title)+'</h3><p class="muted">'+esc(r.category)+' · '+esc(r.area)+'</p><div class="actions"><button class="secondary" data-detail="'+r.id+'">Ver detalhes</button>'+((team.user.role==="presidente"||team.user.area===r.area)&&!r.example?'<button class="secondary" data-edit-record="'+r.id+'">Editar</button>':'')+'</div></article>').join(""):'<div class="empty card"><h3>Nenhum registro encontrado</h3><p class="muted">Tente remover um filtro ou outra palavra-chave.</p></div>')+'</div>'+(pending.length?'<div class="queue"><h3>Sugestões pendentes da sua área</h3>'+pending.map(s=>'<article class="card"><span class="pill">Pendente</span><h3>'+esc(s.title)+'</h3><p>'+esc(s.description)+'</p><div class="actions"><button class="primary" data-approve="'+s.id+'">Aprovar</button><button class="secondary" data-reject="'+s.id+'">Recusar</button></div></article>').join("")+'</div>':'');$("app").innerHTML=teamShell(content)}
function membersView(){api("/api/team/members").then(({users})=>{$("app").innerHTML=teamShell('<div class="panel-head"><div><h2>Gerenciar equipe</h2><p class="muted">Cadastre, redefina e desative contas da equipe.</p></div><button class="primary" data-member-new>Cadastrar pessoa</button></div><div class="grid members-grid">'+users.map(u=>'<article class="card member-card"><span class="pill '+(u.active?'approved':'rejected')+'">'+(u.active?'Ativa':'Desativada')+'</span><h3>'+esc(u.name)+'</h3><p>'+esc(u.email)+'</p><p class="muted">'+esc(u.role)+' · '+esc(u.area)+'</p>'+(u.mustChangePassword?'<p class="muted">Aguardando troca da senha</p>':'')+'<div class="actions"><button class="secondary" data-reset="'+u.id+'">Redefinir acesso</button><button class="secondary" data-toggle="" data-member-id="'+u.id+'" data-active="'+u.active+'">'+(u.active?'Desativar':'Reativar')+'</button></div></article>').join("")+'</div>',"Gerenciar equipe","Controle administrativo das contas da equipe.")}).catch(e=>notify(e.message))}
