function updateStudentTicket(){const card=document.querySelector('#ingressos .card');if(!card)return;const base=Number(currentTicketLot?.price??events[0].price),fee=base*.1,total=base+fee;card.querySelector('.price')&&(card.querySelector('.price').textContent=money(base));card.querySelectorAll('.ticket-breakdown,.ticket-total,.lot-info').forEach(x=>x.remove());const button=card.querySelector('[data-buy="ticket"]');if(currentTicketLot){button.disabled=false;button.textContent='Comprar ingresso';button.insertAdjacentHTML('beforebegin','<p class="muted lot-info">'+esc(currentTicketLot.name)+' · '+currentTicketLot.available+' disponíveis</p>');button.insertAdjacentHTML('afterend','<p class="ticket-breakdown"><span>Ingresso</span><span>'+money(base)+'</span></p><p class="ticket-breakdown"><span>Taxa do site (10%)</span><span>'+money(fee)+'</span></p><p class="price ticket-total">Total '+money(total)+'</p>')}else{button.disabled=true;button.textContent='Esgotado';button.insertAdjacentHTML('beforebegin','<p class="muted lot-info">Todos os lotes estão esgotados.</p>')}}
