document.addEventListener('submit',async e=>{if(e.target.id!=='contact-form')return;e.preventDefault();try{await api('/api/contact',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();notify('Mensagem enviada. A Presidência responderá em breve.')}catch(err){notify(err.message)}});
const oldBuyWithLot=buy;buy=function(id){if(id==='ticket'){if(!currentTicketLot)return notify('Todos os lotes estão esgotados.');cart.push({id:'ticket',name:events[0].title,price:Number(currentTicketLot.price),size:currentTicketLot.name,lotId:currentTicketLot.id,quantity:1});render();notify('Ingresso adicionado ao carrinho.');return}oldBuyWithLot(id)};
const oldCartWithRemove=cartModal;cartModal=function(){if(!cart.length)return notify('Seu carrinho está vazio.');const ticketFee=cart.filter(p=>p.id==='ticket').reduce((s,p)=>s+Number(p.price||0)*.1,0),total=cart.reduce((s,p)=>s+Number(p.price||0),0)+ticketFee,items=ticketFee?[...cart,{id:'site-fee',name:'Taxa do site (10%)',size:'Ingresso',price:ticketFee}]:cart;openModal('Seu carrinho','<div class="cart-items">'+items.map((p,i)=>'<div class="cart-line"><span>'+esc(p.name)+' · '+esc(p.size)+'</span><strong>'+money(p.price)+(p.id!=='site-fee'?'<button type="button" class="link-button" data-remove-cart="'+i+'">Remover</button>':'')+'</strong></div>').join('')+'</div><p class="price cart-total">Total '+money(total)+'</p><div class="pix-box"><strong>Pagamento via Pix</strong><span>Chave: 12981700180</span><small>Anexe o comprovante para o Financeiro confirmar o pedido.</small></div><label class="field">Nome completo<input required name="customerName"></label><label class="field">E-mail<input required type="email" name="customerEmail"></label><label class="field">Comprovante Pix<input type="file" name="receipt" accept="image/*,.pdf"><small>Sem comprovante, a reserva expira em 30 minutos.</small></label>','Enviar pedido',async d=>{try{const receipt=await readReceipt(d.get('receipt'));const result=await api('/api/orders/checkout',{method:'POST',body:JSON.stringify({name:d.get('customerName'),email:d.get('customerEmail'),items:cart.map(p=>({...p,quantity:p.quantity||1})),total,receipt})});cart=[];$('modal').close();render();notify('Pedido '+result.order.id+' enviado ao Financeiro.')}catch(err){notify(err.message)}return false})};
const navBeforeAccess=teamNav;teamNav=function(){let nav=navBeforeAccess();if(team.user&&!['presidente','Financeiro'].includes(team.user.area)&&team.user.role!=='presidente')nav=nav.replace(/<button data-area="Financeiro">[^<]*<\/button>/,'');if(team.user&&!['presidente','Produtos'].includes(team.user.area)&&team.user.role!=='presidente')nav=nav.replace(/<button data-area="Produtos">[^<]*<\/button>/,'');if(team.user?.role==='presidente')nav=nav.replace('</nav>','<button class="archive-tab '+(team.view==='approvals'?'active':'')+'" data-view="approvals">✓ Aprovações</button><button class="archive-tab '+(team.view==='inbox'?'active':'')+'" data-view="inbox">✉ Mensagens</button></nav>');return nav};
function productModal(){openModal('Cadastrar produto','<label class="field">Nome<input required name="name"></label><label class="field">Descrição<textarea required name="description"></textarea></label><label class="field">Foto<input type="file" name="photo" accept="image/*"></label><label class="field">Preço<input required name="price" type="number" min="0" step="0.01"></label><label class="field">Tamanhos<input name="sizes" placeholder="P, M, G, GG"></label><label class="field">Estoque<input required name="stock" type="number" min="0" value="0"></label>','Enviar para aprovação',async d=>{try{const image=await readReceipt(d.get('photo'));await api('/api/team/catalog-products',{method:'POST',body:JSON.stringify({name:d.get('name'),description:d.get('description'),image,price:Number(d.get('price')),sizes:String(d.get('sizes')||'').split(',').map(x=>x.trim()).filter(Boolean),stock:Number(d.get('stock')||0)})});$('modal').close();productsAreaView();notify('Produto enviado para aprovação da Presidência.')}catch(err){notify(err.message)}return false})}
async function productsAreaView(){const data=await api('/api/team/catalog-products'),items=team.user.role==='presidente'?data.products:data.products.filter(x=>x.createdBy===team.user.id||x.status==='Aprovada');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Produtos</h2><p class="muted">Cadastre produtos; a publicação no Shop depende da aprovação da Presidência.</p></div><button class="primary" data-product-new>Novo produto</button></div><div class="grid">'+items.map(p=>'<article class="card"><span class="pill '+(p.status==='Aprovada'?'approved':'')+'">'+esc(p.status)+'</span><h3>'+esc(p.name)+'</h3><p>'+esc(p.description)+'</p><p class="price">'+money(p.price)+'</p><p class="muted">Estoque: '+esc(p.stock)+' · '+esc((p.sizes||[]).join(', ')||'Tamanho único')+'</p></article>').join('')+'</div>','Produtos','Cadastro de produtos para o Shop.')}
async function eventsAreaView(){const data=await api('/api/team/ticket-lots');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Lotes de ingressos</h2><p class="muted">Defina quantidade e preço; a Presidência aprova antes da publicação.</p></div><button class="primary" data-lot-new>Novo lote</button></div><div class="grid">'+data.lots.map(l=>'<article class="card"><span class="pill '+(l.status==='Aprovada'?'approved':'')+'">'+esc(l.status)+'</span><h3>'+esc(l.name)+'</h3><p class="price">'+money(l.price)+'</p><p class="muted">Disponíveis: '+esc(l.available)+' de '+esc(l.quantity)+'</p></article>').join('')+'</div>','Eventos','Gestão de lotes e ingressos.')}
function lotModal(){openModal('Cadastrar lote','<label class="field">Nome do lote<input required name="name" placeholder="1º lote"></label><label class="field">Preço<input required name="price" type="number" min="0" step="0.01"></label><label class="field">Quantidade<input required name="quantity" type="number" min="1"></label>','Enviar para aprovação',async d=>{try{await api('/api/team/ticket-lots',{method:'POST',body:JSON.stringify({name:d.get('name'),price:Number(d.get('price')),quantity:Number(d.get('quantity'))})});$('modal').close();eventsAreaView();notify('Lote enviado para aprovação da Presidência.')}catch(err){notify(err.message)}return false})}
async function approvalsView(){const data=await api('/api/team/approvals');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Fila de aprovação</h2><p class="muted">Nada novo chega aos alunos antes da sua revisão.</p></div></div><div class="grid">'+(data.approvals.length?data.approvals.map(a=>'<article class="card"><span class="pill">Pendente</span><h3>'+esc(a.title)+'</h3><p class="muted">'+esc(a.type)+'</p><div class="actions"><button class="primary" data-approval="'+a.id+'" data-decision="Aprovada">Aprovar publicação</button><button class="secondary" data-approval="'+a.id+'" data-decision="Devolvida">Devolver</button></div></article>').join(''):'<div class="empty card"><h3>Fila vazia</h3><p class="muted">Não há publicações aguardando revisão.</p></div>')+'</div>','Aprovações','Publicações aguardando decisão da Presidência.')}
async function inboxView(){const data=await api('/api/team/messages');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Fale com a Atlética</h2><p class="muted">Mensagens recebidas pelo formulário público.</p></div></div><div class="grid">'+(data.messages.length?data.messages.slice().reverse().map(m=>'<article class="card"><span class="pill">'+esc(m.status)+'</span><h3>'+esc(m.subject)+'</h3><p><strong>'+esc(m.name)+'</strong> · '+esc(m.email)+'</p><p>'+esc(m.message)+'</p></article>').join(''):'<div class="empty card"><h3>Nenhuma mensagem</h3></div>')+'</div>','Mensagens','Caixa de entrada da Presidência.')}
const areaViewBeforeCatalog=areaView;areaView=function(area){if(area==='Produtos'&&(team.user.role==='presidente'||team.user.area==='Produtos'))return productsAreaView();if(area==='Eventos'&&(team.user.role==='presidente'||team.user.area==='Eventos'))return eventsAreaView();return areaViewBeforeCatalog(area)};
const renderTeamBeforeSpecialViews=renderTeam;renderTeam=function(){if(team.view==='approvals'&&team.user?.role==='presidente')return approvalsView();if(team.view==='inbox'&&team.user?.role==='presidente')return inboxView();return renderTeamBeforeSpecialViews()};
$("app").addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.productNew!==undefined)productModal();if(b.dataset.lotNew!==undefined)lotModal();if(b.dataset.approval){try{const note=b.dataset.decision==='Devolvida'?prompt('Observação para a área:')||'':'';await api('/api/team/approvals/'+b.dataset.approval,{method:'PATCH',body:JSON.stringify({status:b.dataset.decision,note})});approvalsView();notify(b.dataset.decision==='Aprovada'?'Publicação aprovada.':'Conteúdo devolvido para ajustes.')}catch(err){notify(err.message)}}});
loadPublicCatalog();
const studentHeaderStyle=student;student=function(){studentHeaderStyle();if(!inTeam()){const c=$('header-cart');if(c){c.style.background='#ce1630';c.style.color='#fff';c.style.border='1px solid #ff8b9e';c.style.borderRadius='6px';c.style.padding='9px 12px';c.style.fontWeight='800';c.style.whiteSpace='nowrap'}}};
function loadPublicContent(){fetch('/api/public/content').then(r=>r.json()).then(x=>{publicContent=x.content||[];if(!inTeam())student()}).catch(()=>{})}loadPublicContent();
const studentWithPublicContent=student;student=function(){studentWithPublicContent();if(!inTeam()&&publicContent.length){const section=document.createElement('section');section.className='shell section';section.id='avisos';section.innerHTML='<div class="eyebrow">Atualizações</div><h2>Novidades da Atlética</h2><div class="grid">'+publicContent.map(c=>'<article class="card"><span class="pill">'+esc(c.kind)+'</span><h3>'+esc(c.title)+'</h3><p>'+esc(c.body)+'</p></article>').join('')+'</div>';document.querySelector('#contato')?.before(section)}};
function publicContentModal(area){const president=team.user?.role==='presidente';openModal(president?'Publicar conteúdo para os alunos':'Enviar conteúdo para os alunos','<label class="field">Área responsável<input name="area" value="'+esc(area||team.user.area||'')+'" readonly></label><label class="field">Tipo<select name="kind"><option>Projeto</option><option>Calendário</option><option>Parceria</option><option>Aviso</option></select></label><label class="field">Título<input required name="title"></label><label class="field">Conteúdo<textarea required name="body" rows="5"></textarea></label>',president?'Publicar agora':'Enviar para aprovação',async d=>{try{await api('/api/team/public-content',{method:'POST',body:JSON.stringify({area:d.get('area'),kind:d.get('kind'),title:d.get('title'),body:d.get('body')})});$('modal').close();renderTeam();notify(president?'Conteúdo publicado diretamente na área dos alunos.':'Conteúdo enviado para aprovação da Presidência.')}catch(err){notify(err.message)}return false})}
const areaViewWithPublicContent=areaView;areaView=function(area){areaViewWithPublicContent(area);if(team.user?.role!=='integrante'&&area!=='Produtos'&&area!=='Eventos'){const head=document.querySelector('.panel-head');if(head&&!head.querySelector('[data-content-new]')){const b=document.createElement('button');b.className=team.user?.role==='presidente'?'primary':'secondary';b.dataset.contentNew=area;b.textContent=team.user?.role==='presidente'?'Publicar projeto diretamente':'Enviar conteúdo para aprovação';head.querySelector('.actions')?.append(b)||head.append(b)}}};
$("app").addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.contentNew!==undefined)publicContentModal(b.dataset.contentNew)});
const renderTeamWithoutWrongSuggestions=renderTeam;renderTeam=function(){renderTeamWithoutWrongSuggestions();if(team.user?.role!=='integrante')document.querySelectorAll('[data-suggest]').forEach(button=>button.remove())};
function appendDeleteButton(parent,attribute,id){if(!parent||parent.querySelector('['+attribute+']'))return;const button=document.createElement('button');button.className='secondary danger-action';button.textContent='Apagar';button.setAttribute(attribute,id);const actions=parent.querySelector('.actions');if(actions)actions.append(button);else parent.append(button)}
const renderTeamWithDeleteActions=renderTeam;renderTeam=async function(){await renderTeamWithDeleteActions();if(!team.user||team.user.role==='integrante')return;document.querySelectorAll('[data-detail]').forEach(button=>{const record=team.records.find(x=>x.id===button.dataset.detail);if(record&&!record.example&&(team.user.role==='presidente'||team.user.area===record.area))appendDeleteButton(button.closest('.card'),'data-delete-record',record.id)});document.querySelectorAll('[data-inventory-edit]').forEach(button=>appendDeleteButton(button.closest('.card'),'data-delete-inventory',button.dataset.inventoryEdit));if(team.view==='Produtos'&&(team.user.role==='presidente'||team.user.area==='Produtos')){try{const data=await api('/api/team/catalog-products');document.querySelectorAll('.card h3').forEach(h=>{const product=data.products.find(x=>x.name===h.textContent.trim());if(product)appendDeleteButton(h.closest('.card'),'data-delete-product',product.id)})}catch{}}if(team.view==='Eventos'&&(team.user.role==='presidente'||team.user.area==='Eventos')){try{const data=await api('/api/team/ticket-lots');document.querySelectorAll('.card h3').forEach(h=>{const lot=data.lots.find(x=>x.name===h.textContent.trim());if(lot)appendDeleteButton(h.closest('.card'),'data-delete-lot',lot.id)})}catch{}}};
document.addEventListener('click',async e=>{const button=e.target.closest('[data-delete-record],[data-delete-inventory],[data-delete-product],[data-delete-lot]');if(!button)return;const type=button.dataset.deleteRecord?'registro':button.dataset.deleteInventory?'item do estoque':button.dataset.deleteProduct?'produto':'lote';if(!confirm('Apagar este '+type+'? Esta ação não pode ser desfeita.'))return;const route=button.dataset.deleteRecord?'/api/team/records/'+button.dataset.deleteRecord:button.dataset.deleteInventory?'/api/team/inventory/'+button.dataset.deleteInventory:button.dataset.deleteProduct?'/api/team/catalog-products/'+button.dataset.deleteProduct:'/api/team/ticket-lots/'+button.dataset.deleteLot;try{await api(route,{method:'DELETE'});renderTeam();notify(type.charAt(0).toUpperCase()+type.slice(1)+' apagado.')}catch(err){notify(err.message)}});
const inventoryViewForProducts=inventoryView;inventoryView=async function(area){if(area==='Produtos'){team.view='Produtos';return renderTeam()}return inventoryViewForProducts(area)};
const renderTeamWithInventory=renderTeam;renderTeam=async function(){await renderTeamWithInventory();if(team.view!=='Produtos'||!team.user)return;try{const data=await api('/api/team/inventory');const items=data.items||[];const canEdit=team.user.role==='presidente'||team.user.area==='Produtos';const section=document.createElement('section');section.className='shell section inventory-management';section.innerHTML='<div class="panel-head"><div><div class="eyebrow">Controle interno</div><h2>Estoque da Atlética</h2><p class="muted">Registre bebidas, materiais e onde cada item está guardado.</p></div>'+(canEdit?'<button class="primary" data-inventory-new>Cadastrar item</button>':'')+'</div><div class="grid inventory-grid">'+(items.length?items.map(x=>'<article class="card inventory-card"><span class="pill">'+esc(x.quantity||'Quantidade não informada')+'</span><h3>'+esc(x.name)+'</h3><p><strong>Onde está:</strong> '+esc(x.location)+'</p>'+(x.notes?'<p class="muted">'+esc(x.notes)+'</p>':'')+(canEdit?'<div class="actions"><button class="secondary" data-inventory-edit="'+x.id+'">Editar</button><button class="secondary danger-action" data-delete-inventory="'+x.id+'">Apagar</button></div>':'')+'</article>').join(''):'<div class="empty card"><h3>Nenhum item no estoque</h3><p class="muted">Cadastre sobras de eventos, bebidas e materiais da Atlética.</p></div>')+'</div>';document.querySelector('#app')?.append(section)}catch(err){notify(err.message)}};
function editProductModal(product){openModal('Editar produto','<label class="field">Nome<input required name="name" value="'+esc(product.name)+'"></label><label class="field">Descrição<textarea required name="description">'+esc(product.description||'')+'</textarea></label><label class="field">Nova foto<input type="file" name="photo" accept="image/*"></label><label class="field">Preço<input required name="price" type="number" min="0" step="0.01" value="'+esc(product.price)+'"></label><label class="field">Tamanhos<input name="sizes" value="'+esc((product.sizes||[]).join(', '))+'"></label><label class="field">Estoque<input required name="stock" type="number" min="0" value="'+esc(product.stock||0)+'"></label>','Salvar alterações',async d=>{try{const file=d.get('photo'),image=file?.size?await readReceipt(file):undefined;const payload={name:d.get('name'),description:d.get('description'),price:Number(d.get('price')),sizes:String(d.get('sizes')||'').split(',').map(x=>x.trim()).filter(Boolean),stock:Number(d.get('stock')||0)};if(image)payload.image=image;await api('/api/team/catalog-products/'+product.id,{method:'PATCH',body:JSON.stringify(payload)});$('modal').close();renderTeam();notify('Produto atualizado.')}catch(err){notify(err.message)}return false})}
function editLotModal(lot){openModal('Editar lote','<label class="field">Nome do lote<input required name="name" value="'+esc(lot.name)+'"></label><label class="field">Preço<input required name="price" type="number" min="0" step="0.01" value="'+esc(lot.price)+'"></label><label class="field">Quantidade total<input required name="quantity" type="number" min="1" value="'+esc(lot.quantity)+'"></label><small>A quantidade não pode ficar menor que as reservas já realizadas.</small>','Salvar alterações',async d=>{try{await api('/api/team/ticket-lots/'+lot.id,{method:'PATCH',body:JSON.stringify({name:d.get('name'),price:Number(d.get('price')),quantity:Number(d.get('quantity'))})});$('modal').close();renderTeam();notify('Lote atualizado.')}catch(err){notify(err.message)}return false})}
const renderTeamWithCatalogEdit=renderTeam;renderTeam=async function(){await renderTeamWithCatalogEdit();if(!team.user||team.user.role==='integrante')return;if(team.view==='Produtos'&&(team.user.role==='presidente'||team.user.area==='Produtos')){try{const data=await api('/api/team/catalog-products');document.querySelectorAll('.card h3').forEach(h=>{const product=data.products.find(x=>x.name===h.textContent.trim());if(product&&h.closest('.card')){const actions=h.closest('.card').querySelector('.actions')||h.closest('.card');if(!actions.querySelector('[data-edit-product]')){const b=document.createElement('button');b.className='secondary';b.textContent='Editar';b.dataset.editProduct=product.id;actions.append(b)}}})}catch{}}if(team.view==='Eventos'&&(team.user.role==='presidente'||team.user.area==='Eventos')){try{const data=await api('/api/team/ticket-lots');document.querySelectorAll('.card h3').forEach(h=>{const lot=data.lots.find(x=>x.name===h.textContent.trim());if(lot&&h.closest('.card')){const actions=h.closest('.card').querySelector('.actions')||h.closest('.card');if(!actions.querySelector('[data-edit-lot]')){const b=document.createElement('button');b.className='secondary';b.textContent='Editar';b.dataset.editLot=lot.id;actions.append(b)}}})}catch{}}};
document.addEventListener('click',async e=>{const button=e.target.closest('[data-edit-product],[data-edit-lot]');if(!button)return;try{const route=button.dataset.editProduct?'/api/team/catalog-products':'/api/team/ticket-lots',data=await api(route),items=button.dataset.editProduct?data.products:data.lots,item=items.find(x=>x.id===(button.dataset.editProduct||button.dataset.editLot));if(item)button.dataset.editProduct?editProductModal(item):editLotModal(item)}catch(err){notify(err.message)}});
let publicTicketLots=[];fetch('/api/public/ticket-lots').then(r=>r.json()).then(data=>{publicTicketLots=data.lots||[]}).catch(()=>{});
function chooseTicketLot(){const lots=publicTicketLots.length?publicTicketLots:(currentTicketLot?[currentTicketLot]:[]);if(!lots.length)return notify('Todos os lotes estão esgotados.');openModal('Escolha o lote do ingresso','<p class="muted">Selecione um lote para adicionar o ingresso ao carrinho.</p><div class="grid lot-choices">'+lots.map(l=>'<button type="button" class="card" data-select-ticket-lot="'+l.id+'"><strong>'+esc(l.name)+'</strong><span>'+money(l.price)+' · '+esc(l.available)+' disponíveis</span></button>').join('')+'</div>','Fechar',()=>{$('modal').close();return false})}
const buyWithLotChoice=buy;buy=function(id){if(id==='ticket'){chooseTicketLot();return}buyWithLotChoice(id)};
document.addEventListener('click',e=>{const button=e.target.closest('[data-select-ticket-lot]');if(!button)return;const lot=publicTicketLots.find(x=>x.id===button.dataset.selectTicketLot);if(!lot)return;cart.push({id:'ticket',name:events[0].title,price:Number(lot.price),size:lot.name,lotId:lot.id,quantity:1});$('modal').close();render();notify('Ingresso adicionado ao carrinho.')});
const studentHideTicketLots=student;student=function(){studentHideTicketLots();if(!inTeam()){document.querySelectorAll('#ingressos .lot-info,#ingressos .ticket-breakdown,#ingressos .ticket-total').forEach(x=>x.remove());const button=document.querySelector('#ingressos [data-buy="ticket"]');if(button&&currentTicketLot){button.textContent='Ver lotes e comprar'}}};
function areaRequestModal(){const president=team.user?.role==='presidente',from=team.user?.area||'';const fromField=president?'<label class="field">Área solicitante<select name="fromArea">'+team.areas.map(a=>'<option>'+esc(a)+'</option>').join('')+'</select></label>':'<input type="hidden" name="fromArea" value="'+esc(from)+'"><p class="muted">Área solicitante: '+esc(from)+'</p>';openModal('Solicitar apoio de outra área',fromField+'<label class="field">Área destinatária<select required name="toArea">'+team.areas.filter(a=>a!==from).map(a=>'<option>'+esc(a)+'</option>').join('')+'</select></label><label class="field">Tipo<select name="kind"><option>Pedido de divulgação</option><option>Pedido de apoio</option><option>Compartilhamento de informação</option></select></label><label class="field">Título<input required name="title" placeholder="Ex.: Divulgar o próximo evento de Esportes"></label><label class="field">Mensagem<textarea required name="body" rows="5" placeholder="Explique o que a outra área precisa fazer."></textarea></label>','Enviar solicitação',async d=>{try{await api('/api/team/requests',{method:'POST',body:JSON.stringify({fromArea:d.get('fromArea'),toArea:d.get('toArea'),kind:d.get('kind'),title:d.get('title'),body:d.get('body')})});$('modal').close();renderTeam();notify('Solicitação enviada para a área destinatária.')}catch(err){notify(err.message)}return false})}
const renderTeamWithAreaRequests=renderTeam;renderTeam=async function(){await renderTeamWithAreaRequests();if(!team.user||!team.areas.includes(team.view))return;const head=document.querySelector('.panel-head');if(head&&!head.querySelector('[data-request-new]')){const button=document.createElement('button');button.className='secondary';button.dataset.requestNew='';button.textContent='Solicitar apoio de outra área';head.querySelector('.actions')?.append(button)||head.append(button)}try{const data=await api('/api/team/requests'),requests=(data.requests||[]).filter(x=>x.fromArea===team.view||x.toArea===team.view||team.user.role==='presidente'),section=document.createElement('section');section.className='shell section area-requests';section.innerHTML='<div class="eyebrow">Integração</div><h2>Comunicação entre áreas</h2><p class="muted">Use este espaço para pedir apoio, divulgação ou informações a outra equipe.</p><div class="grid">'+(requests.length?requests.slice().reverse().map(x=>'<article class="card"><span class="pill '+(x.status==='Atendida'?'approved':x.status==='Recusada'?'rejected':'')+'">'+esc(x.status)+'</span><p class="muted">'+esc(x.fromArea)+' → '+esc(x.toArea)+' · '+esc(x.kind)+'</p><h3>'+esc(x.title)+'</h3><p>'+esc(x.body)+'</p>'+(x.responseNote?'<p class="muted"><strong>Resposta:</strong> '+esc(x.responseNote)+'</p>':'')+((team.user.role==='presidente'||(team.user.role==='diretor'&&team.user.area===x.toArea))&&x.status==='Pendente'?'<div class="actions"><button class="primary" data-request-status="Atendida" data-request-id="'+x.id+'">Marcar como atendida</button><button class="secondary" data-request-status="Recusada" data-request-id="'+x.id+'">Recusar</button></div>':'')+'</article>').join(''):'<div class="empty card"><h3>Nenhuma solicitação</h3><p class="muted">As solicitações enviadas ou recebidas aparecerão aqui.</p></div>')+'</div>';document.querySelector('#app')?.append(section)}catch(err){notify(err.message)}};
document.addEventListener('click',async e=>{const button=e.target.closest('[data-request-new],[data-request-status]');if(!button)return;if(button.dataset.requestNew!==undefined){areaRequestModal();return}try{const note=button.dataset.requestStatus==='Recusada'?prompt('Observação para a área solicitante:')||'':'';await api('/api/team/requests/'+button.dataset.requestId,{method:'PATCH',body:JSON.stringify({status:button.dataset.requestStatus,note})});renderTeam();notify(button.dataset.requestStatus==='Atendida'?'Solicitação marcada como atendida.':'Solicitação recusada.')}catch(err){notify(err.message)}});
teamNav=function(){return '<nav class="tabs" aria-label="Navegacao da equipe">'+team.areas.map(a=>'<button data-area="'+esc(a)+'">'+esc(a)+'</button>').join('')+'<button class="archive-tab '+(team.view==="archive"?'active':'')+'" data-view="archive">Acervo da Tantera</button><button class="archive-tab '+(team.view==="inventory"?'active':'')+'" data-view="inventory">Estoque</button>'+(team.user.role==="presidente"?'<button class="archive-tab '+(team.view==="members"?'active':'')+'" data-view="members">Gerenciar equipe</button>':'')+'</nav>'};
inventoryView=async function(){let items=[];try{items=(await api('/api/team/inventory')).items}catch(e){notify(e.message)}const cards=items.length?items.map(x=>'<article class="card inventory-card"><span class="pill">'+esc(x.quantity||"Quantidade nao informada")+'</span><h3>'+esc(x.name)+'</h3><p><strong>Onde esta:</strong> '+esc(x.location)+'</p><p class="muted"><strong>Area:</strong> '+esc(x.area||"Nao informada")+'</p>'+(x.notes?'<p class="muted">'+esc(x.notes)+'</p>':'')+'<div class="actions"><button class="secondary" data-inventory-edit="'+x.id+'">Editar item</button><button class="secondary danger-action" data-delete-inventory="'+x.id+'">Apagar</button></div></article>').join(''):'<div class="empty card"><h3>Nenhum item cadastrado</h3><p class="muted">Registre sobras, materiais e o local onde estao guardados.</p></div>';const content='<div class="panel-head"><div><h2>Estoque da Atletica</h2><p class="muted">Controle compartilhado para toda a equipe.</p></div><button class="primary" data-inventory-new>Cadastrar item</button></div><div class="grid inventory-grid">'+cards+'</div>';$('app').innerHTML=teamShell(content,"Estoque","Itens remanescentes, materiais e localizacao do estoque.")};
inventoryModalFields=function(old){const area=team.areas;openModal(old?"Editar item do estoque":"Cadastrar item no estoque",'<label class="field">Item<input required name="name" placeholder="Ex.: Garrafas de agua" value="'+esc(old?.name||"")+'"></label><div class="form-row"><label class="field">Quantidade<input required name="quantity" placeholder="Ex.: 6 unidades" value="'+esc(old?.quantity||"")+'"></label><label class="field">Area<select required name="area">'+area.map(a=>'<option '+(a===old?.area?'selected':'')+'>'+esc(a)+'</option>').join('')+'</select></label></div><label class="field">Onde esta?<input required name="location" placeholder="Ex.: deposito, prateleira 2" value="'+esc(old?.location||"")+'"></label><label class="field">Observacoes<textarea name="notes" maxlength="500">'+esc(old?.notes||"")+'</textarea></label>',old?"Salvar alteracoes":"Cadastrar item",async d=>{try{await api(old?'/api/team/inventory/'+old.id:'/api/team/inventory',{method:old?'PATCH':'POST',body:JSON.stringify(Object.fromEntries(d))});$('modal').close();inventoryView();notify(old?"Item atualizado.":"Item cadastrado no estoque.")}catch(e){notify(e.message)}return false})};
productModal=function(){openModal('Cadastrar produto','<label class="field">Nome<input required name="name"></label><label class="field">Descricao<textarea required name="description"></textarea></label><label class="field">Foto<input type="file" name="photo" accept="image/*"></label><label class="field">Preco<input required name="price" type="number" min="0" step="0.01"></label><label class="field">Tamanhos<input name="sizes" placeholder="P, M, G, GG"></label>','Enviar para aprovacao',async d=>{try{const image=await readReceipt(d.get('photo'));await api('/api/team/catalog-products',{method:'POST',body:JSON.stringify({name:d.get('name'),description:d.get('description'),image,price:Number(d.get('price')),sizes:String(d.get('sizes')||'').split(',').map(x=>x.trim()).filter(Boolean)})});$('modal').close();productsAreaView();notify('Produto enviado para aprovacao da Presidencia.')}catch(err){notify(err.message)}return false})};
productsAreaView=async function(){const data=await api('/api/team/catalog-products'),items=team.user.role==='presidente'?data.products:data.products.filter(x=>x.createdBy===team.user.id||x.status==='Aprovada');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Produtos</h2><p class="muted">Cadastre produtos; a publicacao no Shop depende da aprovacao da Presidencia.</p></div><button class="primary" data-product-new>Novo produto</button></div><div class="grid">'+items.map(p=>'<article class="card"><span class="pill '+(p.status==='Aprovada'?'approved':'')+'">'+esc(p.status)+'</span><h3>'+esc(p.name)+'</h3><p>'+esc(p.description)+'</p><p class="price">'+money(p.price)+'</p><p class="muted">'+esc((p.sizes||[]).join(', ')||'Tamanho unico')+'</p></article>').join('')+'</div>','Produtos','Cadastro de produtos para o Shop.')};
editProductModal=function(product){openModal('Editar produto','<label class="field">Nome<input required name="name" value="'+esc(product.name)+'"></label><label class="field">Descricao<textarea required name="description">'+esc(product.description||'')+'</textarea></label><label class="field">Nova foto<input type="file" name="photo" accept="image/*"></label><label class="field">Preco<input required name="price" type="number" min="0" step="0.01" value="'+esc(product.price)+'"></label><label class="field">Tamanhos<input name="sizes" value="'+esc((product.sizes||[]).join(', '))+'"></label>','Salvar alteracoes',async d=>{try{const file=d.get('photo'),image=file?.size?await readReceipt(file):undefined;const payload={name:d.get('name'),description:d.get('description'),price:Number(d.get('price')),sizes:String(d.get('sizes')||'').split(',').map(x=>x.trim()).filter(Boolean)};if(image)payload.image=image;await api('/api/team/catalog-products/'+product.id,{method:'PATCH',body:JSON.stringify(payload)});$('modal').close();renderTeam();notify('Produto atualizado.')}catch(err){notify(err.message)}return false})};
const renderTeamWithSharedInventory=renderTeam;renderTeam=async function(){if(team.view==='inventory'&&team.user)return inventoryView();return renderTeamWithSharedInventory()};
const renderTeamWithoutProductInventory=renderTeam;renderTeam=async function(){if(team.view==='Produtos'&&team.user&&(team.user.role==='presidente'||team.user.area==='Produtos'))return productsAreaView();if(team.view==='inventory'&&team.user)return inventoryView();return renderTeamWithoutProductInventory()};
const studentWithAnonymousContact=student;student=function(){studentWithAnonymousContact();if(!inTeam()){const form=$('contact-form');if(form&&!form.querySelector('[data-anonymous]')){form.insertAdjacentHTML('afterbegin','<label class="field"><span><input type="checkbox" data-anonymous name="anonymous" value="true"> Enviar anonimamente</span></label>');const toggle=form.querySelector('[data-anonymous]'),fields=[form.elements.name,form.elements.email];toggle.addEventListener('change',()=>fields.forEach(x=>{x.required=false;x.disabled=toggle.checked;if(toggle.checked)x.value=''}))}}};
const suggestModalWithAnonymous=suggestModal;suggestModal=function(){openModal("Sugerir material",'<label class="field"><span><input type="checkbox" name="anonymous" value="true"> Enviar anonimamente</span></label><label class="field">Titulo<input required name="title" maxlength="120"></label><div class="form-row"><label class="field">Ano<input required name="year" value="2025" pattern="[0-9]{4}"></label><label class="field">Area<select required name="area">'+team.areas.map(a=>'<option>'+esc(a)+'</option>').join('')+'</select></label></div><label class="field">Categoria<select required name="category">'+team.categories.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select></label><label class="field">Descricao<textarea required name="description" maxlength="700"></textarea></label><label class="field">Palavras-chave<input name="keywords"></label><label class="field">Link do material<input type="url" name="url"></label>',"Enviar para aprovacao",async d=>{const b={title:d.get("title"),year:d.get("year"),area:d.get("area"),category:d.get("category"),description:d.get("description"),keywords:d.get("keywords"),anonymous:d.get("anonymous")==="true",materials:d.get("url")?[{name:"Material online",url:d.get("url")}]:[]};try{await api("/api/team/suggestions",{method:"POST",body:JSON.stringify(b)});$("modal").close();await loadTeam();notify("Sugestao enviada para a Presidencia.")}catch(e){notify(e.message)}return false})};
const publicContentModalWithCalendarGuard=publicContentModal;publicContentModal=function(area){if(team.user?.role==='presidente')return publicContentModalWithCalendarGuard(area);openModal('Enviar conteudo para os alunos','<label class="field">Area responsavel<input name="area" value="'+esc(area||team.user.area||'')+'" readonly></label><label class="field">Tipo<select name="kind"><option>Projeto</option><option>Parceria</option><option>Aviso</option></select></label><label class="field">Titulo<input required name="title"></label><label class="field">Conteudo<textarea required name="body" rows="5"></textarea></label>','Enviar para aprovacao',async d=>{try{await api('/api/team/public-content',{method:'POST',body:JSON.stringify({area:d.get('area'),kind:d.get('kind'),title:d.get('title'),body:d.get('body')})});$('modal').close();renderTeam();notify('Conteudo enviado para aprovacao da Presidencia.')}catch(err){notify(err.message)}return false})};
const buyWithFreshLot=buy;buy=async function(id){if(id==='ticket'){try{const r=await fetch('/api/public/ticket-lots?refresh='+Date.now());const data=await r.json();publicTicketLots=data.lots||[];currentTicketLot=publicTicketLots[0]||null}catch{}}return buyWithFreshLot(id)};
const renderTeamWithSuggestionIdentity=renderTeam;renderTeam=async function(){await renderTeamWithSuggestionIdentity();if(team.user?.role==='presidente'&&team.view==='archive'){document.querySelectorAll('[data-approve],[data-reject]').forEach(button=>{const suggestion=team.suggestions?.find(x=>x.id===(button.dataset.approve||button.dataset.reject)),card=button.closest('.card');if(suggestion&&card&&!card.querySelector('.suggestion-sender')){const sender=suggestion.anonymous?'Anonimo':(suggestion.submittedByName||suggestion.submittedBy||'Identidade nao informada');card.insertAdjacentHTML('afterbegin','<p class="muted suggestion-sender"><strong>Remetente:</strong> '+esc(sender)+'</p>')}})}};
teamNav=function(){return '<nav class="tabs" aria-label="Navegacao da equipe">'+team.areas.map(a=>'<button data-area="'+esc(a)+'">'+esc(a)+'</button>').join('')+'<button class="archive-tab '+(team.view==="archive"?'active':'')+'" data-view="archive">Acervo da Tantera</button><button class="archive-tab '+(team.view==="inventory"?'active':'')+'" data-view="inventory">Estoque</button>'+(team.user.role==='presidente'?'<button class="archive-tab '+(team.view==='calendar'?'active':'')+'" data-view="calendar">Calendario</button><button class="archive-tab '+(team.view==='inbox'?'active':'')+'" data-view="inbox">Mensagens</button><button class="archive-tab '+(team.view==='benefits'?'active':'')+'" data-view="benefits">Plano de associados</button><button class="archive-tab '+(team.view==='approvals'?'active':'')+'" data-view="approvals">Aprovacoes</button><button class="archive-tab '+(team.view==='members'?'active':'')+'" data-view="members">Gerenciar equipe</button>':'')+(team.user.role==='presidente'||team.user.area==='Financeiro'?'<button class="archive-tab '+(team.view==='orders'?'active':'')+'" data-view="orders">Pedidos</button>':'')+'</nav>'};
async function calendarAdminView(){let items=[];try{items=(await api('/api/team/calendar')).events}catch(e){notify(e.message)}const cards=items.map(x=>'<article class="card"><span class="date">'+esc(x.date)+'</span><h3>'+esc(x.title)+'</h3><p>'+esc(x.detail)+'</p><div class="actions"><button class="secondary" data-calendar-edit="'+x.id+'">Editar</button><button class="secondary danger-action" data-calendar-delete="'+x.id+'">Apagar</button></div></article>').join('');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Calendario da Atletica</h2><p class="muted">Edite os eventos exibidos publicamente no site.</p></div><button class="primary" data-calendar-new>Novo evento</button></div><div class="grid">'+(cards||'<div class="empty card"><h3>Nenhum evento cadastrado</h3></div>')+'</div>','Calendario','Area exclusiva da Presidencia.')}
function calendarModal(editId){const load=editId?api('/api/team/calendar').then(r=>r.events.find(x=>x.id===editId)):Promise.resolve(null);load.then(old=>openModal(old?'Editar evento':'Novo evento','<label class="field">Data ou periodo<input required name="date" value="'+esc(old?.date||'')+'" placeholder="Ex.: JUN · 15/06"></label><label class="field">Titulo<input required name="title" value="'+esc(old?.title||'')+'"></label><label class="field">Descricao<textarea required name="detail" rows="4">'+esc(old?.detail||'')+'</textarea></label>',old?'Salvar alteracoes':'Cadastrar evento',async d=>{try{await api(old?'/api/team/calendar/'+old.id:'/api/team/calendar',{method:old?'PATCH':'POST',body:JSON.stringify(Object.fromEntries(d))});$('modal').close();calendarAdminView();loadPublicCalendar();notify(old?'Evento atualizado.':'Evento cadastrado.')}catch(e){notify(e.message)}return false}))}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-calendar-new],[data-calendar-edit],[data-calendar-delete]');if(!b)return;if(b.dataset.calendarNew!==undefined)return calendarModal();if(b.dataset.calendarEdit)return calendarModal(b.dataset.calendarEdit);if(b.dataset.calendarDelete){if(!confirm('Apagar este evento?'))return;try{await api('/api/team/calendar/'+b.dataset.calendarDelete,{method:'DELETE'});calendarAdminView();loadPublicCalendar();notify('Evento apagado.')}catch(err){notify(err.message)}}});
const renderTeamWithCalendar=renderTeam;renderTeam=async function(){if(team.view==='calendar'&&team.user?.role==='presidente')return calendarAdminView();return renderTeamWithCalendar()};
function renderPublicCalendar(){const current=document.querySelector('#calendario');if(!current||inTeam())return;const replacement=section('calendario','Agenda ilustrativa','Proximos eventos','<div class="grid">'+events.map(e=>'<article class="card"><span class="date">'+esc(e.date)+'</span><h3>'+esc(e.title)+'</h3><p class="muted">'+esc(e.detail)+'</p></article>').join('')+'</div>');current.outerHTML=replacement}
async function loadPublicCalendar(){try{const data=await fetch('/api/public/calendar').then(r=>r.json());if(Array.isArray(data.events)&&data.events.length){events.splice(0,events.length,...data.events);renderPublicCalendar()}}catch{}}loadPublicCalendar();

// Administração de lotes, benefícios e eventos históricos.
eventsAreaView=async function(){const data=await api('/api/team/ticket-lots');const cards=data.lots.map(l=>'<article class="card"><span class="pill '+(l.status==='Aprovada'?'approved':'')+'">'+esc(l.status)+'</span><h3>'+esc(l.name)+'</h3><p class="price">'+money(l.price)+'</p><p class="muted">Disponíveis: '+esc(l.available)+' de '+esc(l.quantity)+'</p><div class="actions"><button class="secondary" data-edit-lot="'+l.id+'">Editar</button><button class="secondary" data-lot-advance="'+l.id+'">Avançar lote</button><button class="secondary danger-action" data-delete-lot="'+l.id+'">Apagar</button></div></article>').join('');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Lotes de ingressos</h2><p class="muted">Edite, apague ou avance o lote dentro dos primeiros 5 dias. Depois, somente a Presidência pode alterar.</p></div><button class="primary" data-lot-new>Novo lote</button></div><div class="grid">'+(cards||'<div class="empty card"><h3>Nenhum lote cadastrado</h3></div>')+'</div>','Eventos','Gestão de lotes e ingressos.')};
function lotAdvanceModal(lot){openModal('Avançar lote','<p class="muted">O lote atual será encerrado e um novo lote ficará disponível para compra.</p><label class="field">Nome do novo lote<input required name="name" value="'+esc(lot.name.replace(/\d+º?/,'')+' novo lote')+'"></label><label class="field">Preço<input required name="price" type="number" min="0" step="0.01" value="'+esc(lot.price)+'"></label><label class="field">Quantidade<input required name="quantity" type="number" min="1"></label>','Criar próximo lote',async d=>{try{await api('/api/team/ticket-lots/'+lot.id+'/advance',{method:'POST',body:JSON.stringify({name:d.get('name'),price:Number(d.get('price')),quantity:Number(d.get('quantity'))})});$('modal').close();eventsAreaView();notify('Novo lote criado e disponibilizado para compra.')}catch(e){notify(e.message)}return false})}
benefitsView=async function(){let benefits=[];try{benefits=(await api('/api/team/benefits')).benefits}catch(e){notify(e.message)}const cards=benefits.map(b=>'<article class="card"><span class="pill '+(b.active?'approved':'rejected')+'">'+(b.active?'Ativo':'Desativado')+'</span><h3>'+esc(b.title)+'</h3><p>'+esc(b.description)+'</p>'+(b.partner?'<p class="muted">'+esc(b.partner)+'</p>':'')+'<div class="actions"><button class="secondary" data-benefit-edit="'+b.id+'">Editar</button><button class="secondary danger-action" data-benefit-delete="'+b.id+'">Apagar</button></div></article>').join('');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Benefícios do plano</h2><p class="muted">Somente a Presidência pode adicionar, editar ou apagar benefícios.</p></div><button class="primary" data-benefit-new>Novo benefício</button></div><div class="grid">'+(cards||'<div class="empty card"><h3>Nenhum benefício cadastrado</h3></div>')+'</div>','Plano de associados','Gerencie os benefícios exibidos para os alunos.')};
calendarAdminView=async function(){let items=[];try{items=(await api('/api/team/calendar')).events}catch(e){notify(e.message)}const cards=items.map(x=>'<article class="card"><span class="date">'+esc(x.date)+'</span><span class="pill '+(x.status==='Realizado'?'approved':'')+'">'+esc(x.status||'Futuro')+'</span><h3>'+esc(x.title)+'</h3><p>'+esc(x.detail)+'</p>'+((x.photos||[]).length?'<div class="event-gallery">'+(x.photos||[]).map(p=>'<img src="'+esc(p)+'" alt="Foto de '+esc(x.title)+'">').join('')+'</div>':'')+'<div class="actions"><button class="secondary" data-calendar-edit="'+x.id+'">Editar</button><button class="secondary danger-action" data-calendar-delete="'+x.id+'">Apagar</button></div></article>').join('');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Calendário da Atlética</h2><p class="muted">Cadastre também eventos já realizados e publique as fotos para a galera comprar.</p></div><button class="primary" data-calendar-new>Novo evento</button></div><div class="grid">'+(cards||'<div class="empty card"><h3>Nenhum evento cadastrado</h3></div>')+'</div>','Calendário','Área exclusiva da Presidência.')};
calendarModal=function(editId){const load=editId?api('/api/team/calendar').then(r=>r.events.find(x=>x.id===editId)):Promise.resolve(null);load.then(old=>openModal(old?'Editar evento':'Novo evento','<label class="field">Data ou período<input required name="date" value="'+esc(old?.date||'')+'" placeholder="Ex.: 15/06/2026"></label><label class="field">Título<input required name="title" value="'+esc(old?.title||'')+'"></label><label class="field">Descrição<textarea required name="detail" rows="4">'+esc(old?.detail||'')+'</textarea></label><label class="field">Status<select name="status"><option '+(old?.status!=='Realizado'?'selected':'')+'>Futuro</option><option '+(old?.status==='Realizado'?'selected':'')+'>Realizado</option></select></label><label class="field">Adicionar foto do evento<input type="file" name="photo" accept="image/*"></label>',old?'Salvar alterações':'Cadastrar evento',async d=>{try{const photo=await readReceipt(d.get('photo'));const photos=[...(old?.photos||[])];if(photo)photos.push(photo);await api(old?'/api/team/calendar/'+old.id:'/api/team/calendar',{method:old?'PATCH':'POST',body:JSON.stringify({date:d.get('date'),title:d.get('title'),detail:d.get('detail'),status:d.get('status'),photos})});$('modal').close();calendarAdminView();loadPublicCalendar();notify(old?'Evento atualizado.':'Evento cadastrado.')}catch(e){notify(e.message)}return false}))};
renderPublicCalendar=function(){const current=document.querySelector('#calendario');if(!current||inTeam())return;const replacement=section('calendario','Agenda da Atlética','Eventos e fotos','<div class="grid">'+events.map(e=>'<article class="card"><span class="date">'+esc(e.date)+'</span><span class="pill '+(e.status==='Realizado'?'approved':'')+'">'+esc(e.status||'Futuro')+'</span><h3>'+esc(e.title)+'</h3><p class="muted">'+esc(e.detail)+'</p>'+((e.photos||[]).length?'<div class="event-gallery">'+e.photos.map(p=>'<img src="'+esc(p)+'" alt="Foto de '+esc(e.title)+'">').join('')+'</div>':'')+'</article>').join('')+'</div>');current.outerHTML=replacement};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-lot-advance],[data-benefit-delete]');if(!b)return;if(b.dataset.lotAdvance){try{const data=await api('/api/team/ticket-lots'),lot=data.lots.find(x=>x.id===b.dataset.lotAdvance);if(lot)lotAdvanceModal(lot)}catch(err){notify(err.message)}}if(b.dataset.benefitDelete){if(!confirm('Apagar este benefício?'))return;try{await api('/api/team/benefits/'+b.dataset.benefitDelete,{method:'DELETE'});benefitsView();notify('Benefício apagado.')}catch(err){notify(err.message)}}});

