eventsAreaView=async function(){let items=[];try{items=(await api('/api/team/events')).events||[]}catch(e){notify(e.message)}const cards=items.map(event=>'<article class="card"><span class="date">'+esc(event.date)+'</span><span class="pill '+(event.status==='Realizado'?'approved':'')+'">'+esc(event.status||'Futuro')+'</span><h3>'+esc(event.title)+'</h3><p>'+esc(event.detail)+'</p><p class="muted">'+(event.lots||[]).length+' lote(s) configurado(s)'+((event.lots||[]).length?' · '+event.lots.map(l=>esc(l.name)+' ('+money(l.price)+')').join(' · '):'')+'</p>'+((event.photos||[]).length?'<div class="event-gallery">'+event.photos.map(p=>'<img src="'+esc(p)+'" alt="Foto de '+esc(event.title)+'">').join('')+'</div>':'<p class="muted">Nenhuma foto adicionada.</p>')+'<div class="actions"><button class="secondary" data-event-edit="'+event.id+'">Editar evento e fotos</button><button class="secondary danger-action" data-event-delete="'+event.id+'">Apagar evento</button></div></article>').join('');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Eventos</h2><p class="muted">Crie o evento, defina como será a venda e adicione as fotos depois da realização.</p></div><button class="primary" data-event-new>Novo evento</button></div><div class="grid">'+(cards||'<div class="empty card"><h3>Nenhum evento cadastrado</h3><p class="muted">Cadastre o primeiro evento da Atlética.</p></div>')+'</div>','Eventos','Eventos, lotes de venda e fotos.')};
