loadPublicCalendar=async function(){try{const data=await fetch('/api/public/calendar').then(r=>r.json());events.splice(0,events.length,...(Array.isArray(data.events)?data.events:[]));if(events.length)renderPublicCalendar();else hideEmptyPublicCalendar()}catch{}};loadPublicCalendar();
function eventModal(editId=''){const load=editId?api('/api/team/events').then(r=>(r.events||[]).find(x=>x.id===editId)):Promise.resolve(null);load.then(old=>{const lots=(old?.lots||[]).map(l=>[l.name,l.price,l.quantity].join(' | ')).join('\n');openModal(old?'Editar evento':'Novo evento','<label class="field">Data ou período<input required name="date" value="'+esc(old?.date||'')+'" placeholder="Ex.: 15/06/2026"></label><label class="field">Nome do evento<input required name="title" value="'+esc(old?.title||'')+'"></label><label class="field">Descrição<textarea required name="detail" rows="4">'+esc(old?.detail||'')+'</textarea></label><label class="field">Status<select name="status"><option '+(old?.status!=='Realizado'?'selected':'')+'>Futuro</option><option '+(old?.status==='Realizado'?'selected':'')+'>Realizado</option></select></label><label class="field">Lotes de venda<textarea name="lots" rows="5" placeholder="Um por linha: Nome do lote | preço | quantidade">'+esc(lots)+'</textarea><small>Exemplo: 1º lote | 25 | 50</small></label><label class="field">Fotos do evento<input type="file" name="photos" accept="image/*" multiple><small>Adicione fotos agora ou depois que o evento acontecer.</small></label>',old?'Salvar evento':'Criar evento',async d=>{try{const files=d.getAll('photos').filter(f=>f?.size),photos=await Promise.all(files.map(readReceipt)),lotLines=String(d.get('lots')||'').split('\n').map(x=>x.trim()).filter(Boolean),lots=lotLines.map(line=>{const [name,price,quantity]=line.split('|').map(x=>x.trim());return {name,price:Number(price),quantity:Number(quantity)}});if(old){await api('/api/team/events/'+old.id,{method:'PATCH',body:JSON.stringify({date:d.get('date'),title:d.get('title'),detail:d.get('detail'),status:d.get('status'),photos:[...(old.photos||[]),...photos]})})}else{await api('/api/team/events',{method:'POST',body:JSON.stringify({date:d.get('date'),title:d.get('title'),detail:d.get('detail'),status:d.get('status'),photos,lots})})}$('modal').close();eventsAreaView();loadPublicEvents();notify(old?'Evento atualizado.':'Evento criado com lotes de venda.')}catch(e){notify(e.message)}return false})})}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-event-new],[data-event-edit],[data-event-delete]');if(!b)return;if(b.dataset.eventNew!==undefined)return eventModal();if(b.dataset.eventEdit)return eventModal(b.dataset.eventEdit);if(b.dataset.eventDelete){if(!confirm('Apagar este evento e seus lotes?'))return;try{await api('/api/team/events/'+b.dataset.eventDelete,{method:'DELETE'});eventsAreaView();loadPublicEvents();notify('Evento apagado.')}catch(err){notify(err.message)}}});

// Cada registro do Acervo pode guardar um PDF como material anexado.
directRecordModal=function(editId=""){const old=editId?team.records.find(r=>r.id===editId):null,editableArea=team.user.role==="presidente"?team.areas:(team.user.area?[team.user.area]:[]);openModal(old?"Editar registro":"Novo registro",'<label class="field">Título<input required name="title" value="'+esc(old?.title||"")+'"></label><div class="form-row"><label class="field">Ano<input required name="year" pattern="[0-9]{4}" value="'+esc(old?.year||"2025")+'"></label><label class="field">Área<select required name="area">'+editableArea.map(a=>'<option '+((old?.area||team.user.area)===a?'selected':'')+'>'+esc(a)+'</option>').join("")+'</select></label></div><label class="field">Categoria<select required name="category">'+team.categories.map(c=>'<option '+(old?.category===c?'selected':'')+'>'+esc(c)+'</option>').join("")+'</select></label><label class="field">Descrição<textarea required name="description">'+esc(old?.description||"")+'</textarea></label><label class="field">Palavras-chave<input name="keywords" value="'+esc(old?.keywords||"")+'"></label><label class="field">Documento PDF<input type="file" name="pdf" accept="application/pdf,.pdf"><small>Opcional. O PDF ficará disponível nos detalhes do registro.</small></label>',old?"Salvar alterações":"Publicar registro",async d=>{try{const pdf=await readReceipt(d.get('pdf')),materials=[...(old?.materials||[])];if(pdf)materials.push({name:d.get('pdf')?.name||'Documento PDF',url:pdf,type:'application/pdf'});const payload={title:d.get('title'),year:d.get('year'),area:d.get('area'),category:d.get('category'),description:d.get('description'),keywords:d.get('keywords'),materials};await api(old?'/api/team/records/'+old.id:'/api/team/records',{method:old?'PATCH':'POST',body:JSON.stringify(payload)});$('modal').close();await loadTeam();notify(old?'Registro atualizado.':'Registro publicado.')}catch(e){notify(e.message)}return false})};
detail=function(id){const r=team.records.find(x=>x.id===id);if(!r)return;openModal(r.title,'<div class="detail-head"><span class="date">GESTÃO '+esc(r.year)+'</span><span class="pill">'+esc(r.category)+'</span></div><p><strong>Área responsável:</strong> '+esc(r.area)+'</p><p>'+esc(r.description)+'</p><h4>Materiais disponíveis</h4><ul>'+(r.materials?.length?r.materials.map(m=>'<li><a target="_blank" rel="noreferrer" '+(m.type==='application/pdf'?'download="'+esc(m.name||'documento.pdf')+'" ':'')+'href="'+esc(m.url||"#")+'">'+esc(m.name||"Abrir material")+' ↗</a>'+(m.type==='application/pdf'?'<small class="muted"> Documento PDF</small>':'')+'</li>').join(""):'<li>Nenhum material anexado.</li>')+'</ul>',"Fechar",()=>{})};
const unrestrictedNav=teamNav;teamNav=function(){if(team.user?.role==='presidente')return unrestrictedNav();const area=team.user?.area||'';return '<nav class="tabs" aria-label="Navegação da equipe"><button data-area="'+esc(area)+'" class="active">'+esc(area)+'</button><button class="archive-tab '+(team.view==='archive'?'active':'')+'" data-view="archive">Acervo da Tantera</button><button class="archive-tab '+(team.view==='inventory'?'active':'')+'" data-view="inventory">Estoque</button>'+(area==='Financeiro'?'<button class="archive-tab '+(team.view==='orders'?'active':'')+'" data-view="orders">Pedidos</button>':'')+'</nav>'};

function financeLabel(type){return ({saldo:'Quanto temos',gasto:'Gasto',assinatura:'Assinatura',recebido:'Valor recebido'})[type]||type}
function financeMoney(value){return money(Number(value||0))}
function financeModal(){openModal('Adicionar lançamento','<label class="field">Tipo<select required name="type"><option value="saldo">Quanto temos</option><option value="gasto">Gasto</option><option value="assinatura">Assinatura</option><option value="recebido">Valor recebido</option></select></label><label class="field">Valor<input required name="amount" type="number" min="0" step="0.01" placeholder="0,00"></label><label class="field">Descrição<input name="description" maxlength="160" placeholder="Ex.: saldo em caixa, mensalidade, compra de material"></label>','Salvar lançamento',async d=>{try{await api('/api/team/finance',{method:'POST',body:JSON.stringify({type:d.get('type'),amount:Number(d.get('amount')),description:d.get('description')})});$('modal').close();await financeView();notify('Lançamento salvo.')}catch(e){notify(e.message)}return false})}
async function financeView(){let entries=[];try{entries=(await api('/api/team/finance')).entries||[]}catch(e){notify(e.message)}const totals=entries.reduce((out,e)=>{out[e.type]=(out[e.type]||0)+Number(e.amount||0);return out},{}),balance=(totals.saldo||0)+(totals.recebido||0)+(totals.assinatura||0)-(totals.gasto||0),cards=[['saldo','Quanto temos',totals.saldo||0],['recebido','Valores recebidos',totals.recebido||0],['assinatura','Assinaturas',totals.assinatura||0],['gasto','Gastos',totals.gasto||0]];const rows=entries.slice().reverse().map(e=>'<article class="card"><div class="archive-meta"><span class="pill">'+esc(financeLabel(e.type))+'</span><span class="date">'+new Date(e.createdAt).toLocaleDateString('pt-BR')+'</span></div><h3>'+financeMoney(e.amount)+'</h3>'+(e.description?'<p class="muted">'+esc(e.description)+'</p>':'')+'<button class="secondary danger-action" data-finance-delete="'+e.id+'">Apagar lançamento</button></article>').join('');const content='<div class="panel-head"><div><h2>Calculadora financeira</h2><p class="muted">Registre o saldo, gastos, assinaturas e valores recebidos para acompanhar o caixa da Atlética.</p></div><button class="primary" data-finance-new>Adicionar lançamento</button></div><div class="grid">'+cards.map(c=>'<article class="card"><span class="date">'+c[1]+'</span><h3>'+financeMoney(c[2])+'</h3></article>').join('')+'</div><article class="card"><span class="date">SALDO CALCULADO</span><h2>'+financeMoney(balance)+'</h2><p class="muted">Quanto temos + valores recebidos + assinaturas − gastos.</p></article><h3 style="margin-top:28px">Lançamentos</h3><div class="grid">'+(rows||'<div class="empty card"><h3>Nenhum lançamento</h3><p class="muted">Adicione o primeiro valor do caixa.</p></div>')+'</div>';$('app').innerHTML=teamShell(content,'Financeiro','Controle do caixa e dos valores da Atlética.')}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-finance-new],[data-finance-delete]');if(!b)return;if(b.dataset.financeNew!==undefined)return financeModal();if(b.dataset.financeDelete){if(!confirm('Apagar este lançamento?'))return;try{await api('/api/team/finance/'+b.dataset.financeDelete,{method:'DELETE'});await financeView();notify('Lançamento apagado.')}catch(err){notify(err.message)}}});
