calendarAdminView=async function(){let items=[];try{items=(await api('/api/team/calendar')).events}catch(e){notify(e.message)}const cards=items.map(x=>'<article class="card"><span class="date">'+esc(x.date)+'</span><span class="pill '+(x.status==='Realizado'?'approved':'')+'">'+esc(x.status||'Futuro')+'</span><h3>'+esc(x.title)+'</h3><p>'+esc(x.detail)+'</p><div class="actions"><button class="secondary" data-calendar-edit="'+x.id+'">Editar</button><button class="secondary danger-action" data-calendar-delete="'+x.id+'">Apagar</button></div></article>').join('');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Calendário</h2><p class="muted">Cadastre programações que aparecerão na seção pública Calendário. Para ingressos, use a área Eventos.</p></div><button class="primary" data-calendar-new>Novo item no calendário</button></div><div class="grid">'+(cards||'<div class="empty card"><h3>Nenhum item no calendário</h3></div>')+'</div>','Calendário','Área exclusiva da Presidência.')};
calendarModal=function(editId){const load=editId?api('/api/team/calendar').then(r=>r.events.find(x=>x.id===editId)):Promise.resolve(null);load.then(old=>openModal(old?'Editar item do calendário':'Novo item no calendário','<label class="field">Data ou período<input required name="date" value="'+esc(old?.date||'')+'" placeholder="Ex.: 15/06/2026"></label><label class="field">Título da programação<input required name="title" value="'+esc(old?.title||'')+'"></label><label class="field">Descrição<textarea required name="detail" rows="4">'+esc(old?.detail||'')+'</textarea></label>',old?'Salvar item':'Adicionar ao calendário',async d=>{try{await api(old?'/api/team/calendar/'+old.id:'/api/team/calendar',{method:old?'PATCH':'POST',body:JSON.stringify(Object.fromEntries(d))});$('modal').close();calendarAdminView();loadPublicCalendar();notify(old?'Item atualizado.':'Item adicionado ao calendário.')}catch(e){notify(e.message)}return false}))};
// latest feature overrides
async function watermarkPhoto(file){const original=await readReceipt(file);return new Promise(resolve=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0);ctx.save();ctx.globalAlpha=.38;ctx.fillStyle='#fff';ctx.font=Math.max(18,image.width/18)+'px Arial';ctx.rotate(-.35);for(let y=-image.height;y<image.height*2;y+=110)for(let x=-image.width;x<image.width*2;x+=280)ctx.fillText('TANTERA',x,y);ctx.restore();resolve({original,watermarked:canvas.toDataURL('image/jpeg',.88),name:file.name})};image.src=original})}
eventModal=function(editId=''){const load=editId?api('/api/team/events').then(r=>(r.events||[]).find(x=>x.id===editId)):Promise.resolve(null);load.then(old=>{const photos=old?.photos||[];openModal(old?'Editar evento':'Novo evento','<label class="field">Data (somente números: DDMMAAAA)<input required name="date" inputmode="numeric" pattern="[0-9]{8}" maxlength="8" value="'+esc(old?.date||'')+'" placeholder="15062026"></label><label class="field">Nome do evento<input required name="title" value="'+esc(old?.title||'')+'"></label><label class="field">Descrição<textarea required name="detail" rows="4">'+esc(old?.detail||'')+'</textarea></label><label class="field">Status<select name="status"><option '+(old?.status!=='Realizado'?'selected':'')+'>Futuro</option><option '+(old?.status==='Realizado'?'selected':'')+'>Realizado</option></select></label>'+(old?'':'<div class="form-row"><label class="field">Quantidade de lotes<input required name="lotCount" type="number" min="1" max="20" value="1"></label><label class="field">Preço de cada lote<input required name="lotPrice" type="number" min="0" step="0.01" placeholder="25"></label></div><label class="field">Ingressos por lote <span class="muted">(opcional)</span><input name="lotQuantity" type="number" min="1" placeholder="Deixe vazio para ilimitado"></label>')+'<label class="field">Fotos para venda <span class="muted">(opcional)</span><input type="file" name="photos" accept="image/*" multiple><small>A foto com marca d’água aparece no site; a original será liberada após o pagamento.</small></label>',old?'Salvar evento':'Criar evento',async d=>{try{const files=d.getAll('photos').filter(f=>f?.size),newPhotos=await Promise.all(files.map(watermarkPhoto));if(old)await api('/api/team/events/'+old.id,{method:'PATCH',body:JSON.stringify({date:String(d.get('date')).replace(/\D/g,''),title:d.get('title'),detail:d.get('detail'),status:d.get('status'),photos:[...photos,...newPhotos]})});else await api('/api/team/events',{method:'POST',body:JSON.stringify({date:String(d.get('date')).replace(/\D/g,''),title:d.get('title'),detail:d.get('detail'),status:d.get('status'),photos:newPhotos,lotCount:Number(d.get('lotCount')),lotPrice:Number(d.get('lotPrice')),lotQuantity:d.get('lotQuantity')||null})});$('modal').close();eventsAreaView();loadPublicEvents();notify(old?'Evento atualizado.':'Evento criado com lotes de venda.')}catch(e){notify(e.message)}return false})})};
directRecordModal=function(editId=''){const old=editId?team.records.find(r=>r.id===editId):null,areas=team.user.role==='presidente'?team.areas:(team.user.area?[team.user.area]:[]);openModal(old?'Editar registro':'Novo registro','<label class="field">Título<input required name="title" value="'+esc(old?.title||'')+'"></label><div class="form-row"><label class="field">Ano<input required name="year" pattern="[0-9]{4}" value="'+esc(old?.year||'2025')+'"></label><label class="field">Área<select required name="area">'+areas.map(a=>'<option '+((old?.area||team.user.area)===a?'selected':'')+'>'+esc(a)+'</option>').join('')+'</select></label></div><label class="field">Categoria<select required name="category">'+team.categories.map(c=>'<option '+(old?.category===c?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select></label><label class="field">Descrição<textarea required name="description">'+esc(old?.description||'')+'</textarea></label><label class="field">Arquivos do projeto <span class="muted">PDF ou Word</span><input type="file" name="documents" multiple accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></label>',old?'Salvar alterações':'Publicar registro',async d=>{try{const files=d.getAll('documents').filter(f=>f?.size),materials=[...(old?.materials||[]),...(await Promise.all(files.map(async f=>({name:f.name,url:await readReceipt(f),type:f.type||'application/octet-stream'}))))];await api(old?'/api/team/records/'+old.id:'/api/team/records',{method:old?'PATCH':'POST',body:JSON.stringify({title:d.get('title'),year:d.get('year'),area:d.get('area'),category:d.get('category'),description:d.get('description'),materials})});$('modal').close();await loadTeam();notify(old?'Registro atualizado.':'Registro publicado.')}catch(e){notify(e.message)}return false})};
publicContentModal=function(area){const president=team.user?.role==='presidente';openModal(president?'Publicar conteúdo para os alunos':'Publicar projeto para os alunos','<label class="field">Área responsável<input name="area" value="'+esc(area||team.user.area||'')+'" readonly></label><label class="field">Tipo<select name="kind"><option>Projeto</option><option>Parceria</option><option>Aviso</option></select></label><label class="field">Título<input required name="title"></label><label class="field">Conteúdo<textarea required name="body" rows="5"></textarea></label><label class="field">Arquivos do projeto <span class="muted">PDF ou Word (opcional)</span><input type="file" name="documents" multiple accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></label>',president?'Publicar agora':'Publicar',async d=>{try{const files=d.getAll('documents').filter(f=>f?.size),materials=await Promise.all(files.map(async f=>({name:f.name,url:await readReceipt(f),type:f.type||'application/octet-stream'})));await api('/api/team/public-content',{method:'POST',body:JSON.stringify({area:d.get('area'),kind:d.get('kind'),title:d.get('title'),body:d.get('body'),materials})});$('modal').close();renderTeam();loadPublicContent();notify('Projeto publicado na área dos alunos.')}catch(err){notify(err.message)}return false})};
function contentMaterials(items){return (items||[]).length?'<ul class="materials">'+items.map(m=>'<li><a target="_blank" rel="noreferrer" href="'+esc(m.url||'#')+'">'+esc(m.name||'Abrir arquivo')+' ↗</a></li>').join('')+'</ul>':''}
function renderApprovedContent(){if(inTeam())return;document.querySelector('#atualizacoes')?.remove();if(!publicContent.length)return;const html=section('atualizacoes','Projetos e novidades','Projetos da Atlética','<div class="grid">'+publicContent.map(c=>'<article class="card"><span class="pill">'+esc(c.kind||'Projeto')+'</span><h3>'+esc(c.title)+'</h3><p class="muted">'+esc(c.body)+'</p>'+contentMaterials(c.materials)+'</article>').join('')+'</div>');document.querySelector('#associados')?.after(document.createRange().createContextualFragment(html))}
loadPublicContent=async function(){try{const data=await fetch('/api/public/content').then(r=>r.json());publicContent=Array.isArray(data.content)?data.content:[]}catch{publicContent=[]}renderApprovedContent();if(!inTeam())student()};loadPublicContent();
const areaViewWithContent=areaView;areaView=async function(area){await Promise.resolve(areaViewWithContent(area));if(!team.user||!area||area==='Produtos'||area==='Eventos')return;let items=[];try{items=(await api('/api/team/public-content')).content||[]}catch{}const visible=items.filter(x=>x.area===area||team.user.role==='presidente');if(!visible.length)return;document.querySelector('#app')?.insertAdjacentHTML('beforeend','<section class="section"><div class="panel-head"><div><h2>Projetos publicados</h2><p class="muted">Conteúdos desta área que aparecem para os alunos.</p></div></div><div class="grid">'+visible.map(x=>'<article class="card"><span class="pill approved">'+esc(x.status||'Aprovada')+'</span><h3>'+esc(x.title)+'</h3><p>'+esc(x.body)+'</p>'+contentMaterials(x.materials)+'<button class="secondary danger-action" data-public-content-delete="'+x.id+'">Apagar</button></article>').join('')+'</div></section>')};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-public-content-delete]');if(!b)return;if(!confirm('Apagar este projeto?'))return;try{await api('/api/team/public-content/'+b.dataset.publicContentDelete,{method:'DELETE'});await renderTeam();notify('Projeto apagado.')}catch(err){notify(err.message)}});
