const internalProjectAreas=new Set(['Captação','Projetos','Digital','Esportes','E-sports']);
const publicContentModalBeforeInternal=publicContentModal;publicContentModal=function(area){if(!internalProjectAreas.has(area))return publicContentModalBeforeInternal(area);const president=team.user?.role==='presidente';openModal('Novo projeto da área','<label class="field">Área responsável<input name="area" value="'+esc(area)+'" readonly></label><label class="field">Título<input required name="title"></label><label class="field">Descrição<textarea required name="body" rows="5"></textarea></label><label class="field">Arquivos do projeto <span class="muted">PDF ou Word (opcional)</span><input type="file" name="documents" multiple accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></label>',president?'Salvar projeto':'Salvar projeto na área',async d=>{try{const files=d.getAll('documents').filter(f=>f?.size),materials=await Promise.all(files.map(async f=>({name:f.name,url:await readReceipt(f),type:f.type||'application/octet-stream'})));await api('/api/team/records',{method:'POST',body:JSON.stringify({title:d.get('title'),year:String(new Date().getFullYear()),area:d.get('area'),category:'Projetos',description:d.get('body'),keywords:'',materials})});$('modal').close();await loadTeam();notify('Projeto salvo na área '+area+'.')}catch(err){notify(err.message)}return false})};
