productsAreaView=async function(){let data={products:[]};try{data=await api('/api/team/catalog-products')}catch(e){notify(e.message)}const items=team.user?.role==='presidente'?data.products:(data.products||[]).filter(x=>x.createdBy===team.user?.id||x.status==='Aprovada');const cards=items.map(p=>'<article class="card"><span class="pill '+(p.status==='Aprovada'?'approved':'')+'">'+esc(p.status||'')+'</span><h3>'+esc(p.name)+'</h3><p>'+esc(p.description||'')+'</p><p class="price">'+money(p.price)+'</p><p class="muted">'+esc((p.sizes||[]).join(', ')||'Tamanho único')+'</p><div class="actions"><button class="secondary" data-edit-product="'+p.id+'">Editar</button><button class="secondary danger-action" data-delete-product="'+p.id+'">Apagar produto</button></div></article>').join('');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Produtos</h2><p class="muted">Cadastre, edite ou apague os produtos da Atlética.</p></div><button class="primary" data-product-new>Novo produto</button></div><div class="grid">'+(cards||'<div class="empty card"><h3>Nenhum produto cadastrado</h3></div>')+'</div>','Produtos','Produtos da Atlética.')};
const renderPublicEventsBeforePhotoPairs=renderPublicEvents;renderPublicEvents=function(){if(inTeam())return;document.querySelector('#eventos')?.remove();if(!publicEvents.length)return;const html=section('eventos','Eventos','Eventos','<div class="grid">'+publicEvents.map(e=>'<article class="card"><span class="date">'+esc(e.date)+'</span><span class="pill '+(e.status==='Realizado'?'approved':'')+'">'+esc(e.status||'Futuro')+'</span><h3>'+esc(e.title)+'</h3><p class="muted">'+esc(e.detail)+'</p>'+((e.lots||[]).length?'<p class="muted">Lotes: '+e.lots.map(l=>esc(l.name)+' · '+money(l.price)).join(' · ')+'</p><button class="primary" data-buy="ticket">Adicionar ingresso ao carrinho</button>':'')+((e.photos||[]).length?'<div class="event-gallery">'+e.photos.map((p,i)=>{const photo=typeof p==='string'?{watermarked:p}:p;return '<figure class="photo-sale"><img src="'+esc(photo.watermarked||photo.original||'#')+'" alt="Foto '+(i+1)+' de '+esc(e.title)+'"><figcaption>Foto '+(i+1)+' · com marca d’água</figcaption></figure>'}).join('')+'</div>':'')+'</article>').join('')+'</div>');const shopSection=document.querySelector('#shop');if(shopSection)shopSection.after(document.createRange().createContextualFragment(html))};
chooseTicketLot=function(){const lots=publicTicketLots.length?publicTicketLots:(currentTicketLot?[currentTicketLot]:[]);if(!lots.length)return notify('Todos os lotes estão esgotados.');openModal('Escolha o lote do ingresso','<p class="muted">Escolha um lote e clique em “Adicionar ao carrinho”.</p><div class="grid lot-choices">'+lots.map(l=>'<button type="button" class="card" data-select-ticket-lot="'+l.id+'"><strong>'+esc(l.name)+'</strong><span>'+money(l.price)+' · Adicionar ao carrinho</span></button>').join('')+'</div>','Fechar',()=>{$('modal').close();return false})};
