eventsAreaView=async function(){let items=[];try{items=(await api('/api/team/events')).events||[]}catch(e){notify(e.message)}const cards=items.map(event=>'<article class="card"><span class="date">'+esc(event.date)+'</span><span class="pill '+(event.status==='Realizado'?'approved':'')+'">'+esc(event.status||'Futuro')+'</span><h3>'+esc(event.title)+'</h3><p>'+esc(event.detail)+'</p><p class="muted">'+(event.lots||[]).length+' lote(s) configurado(s)</p>'+((event.photos||[]).length?'<div class="event-gallery">'+event.photos.map((p,i)=>{const photo=typeof p==='string'?{watermarked:p}:p;return '<figure class="photo-sale"><div class="form-row"><img src="'+esc(photo.watermarked||photo.original||'#')+'" alt="Foto '+(i+1)+' com marca d’água"><img src="'+esc(photo.original||photo.watermarked||'#')+'" alt="Foto '+(i+1)+' sem marca d’água"></div><figcaption>Foto '+(i+1)+' · com marca d’água / sem marca d’água</figcaption></figure>'}).join('')+'</div>':'<p class="muted">Nenhuma foto adicionada.</p>')+'<div class="actions"><button class="secondary" data-event-edit="'+event.id+'">Editar evento e fotos</button><button class="secondary danger-action" data-event-delete="'+event.id+'">Apagar evento</button></div></article>').join('');$('app').innerHTML=teamShell('<div class="panel-head"><div><h2>Eventos</h2><p class="muted">Cadastre o evento, os lotes e cada foto com sua versão marcada e original.</p></div><button class="primary" data-event-new>Novo evento</button></div><div class="grid">'+(cards||'<div class="empty card"><h3>Nenhum evento cadastrado</h3></div>')+'</div>','Eventos','Eventos, lotes de venda e fotos.')};
const studentTicketButtonText=student;student=function(){studentTicketButtonText();if(!inTeam()){const button=document.querySelector('#ingressos [data-buy="ticket"]');if(button&&!button.disabled)button.textContent='Adicionar ao carrinho'}};if(!inTeam())student();
