const memberModalBeforePresidency=memberModal;memberModal=function(){openModal('Cadastrar pessoa','<label class="field">Nome<input required name="name"></label><label class="field">E-mail<input required type="email" name="email"></label><div class="form-row"><label class="field">Cargo<select name="role"><option value="presidente">Presidência</option><option value="diretor">Diretor</option><option value="integrante">Integrante</option></select></label><label class="field">Área<select name="area">'+team.areas.map(a=>'<option>'+esc(a)+'</option>').join('')+'</select></label></div><label class="field">Senha temporária<input required minlength="3" name="temporaryPassword" type="password"><small>A pessoa deverá trocar a senha no primeiro acesso.</small></label>','Cadastrar',async d=>{try{const payload=Object.fromEntries(d),route=payload.role==='presidente'?'/api/team/presidents':'/api/team/members';await api(route,{method:'POST',body:JSON.stringify(payload)});$('modal').close();membersView();notify(payload.role==='presidente'?'Presidência cadastrada.':'Conta cadastrada.')}catch(e){notify(e.message)}return false})};
const eventsAreaWithPhotoEdit=eventsAreaView;eventsAreaView=async function(){await eventsAreaWithPhotoEdit();document.querySelectorAll('.event-gallery figcaption,.event-gallery small').forEach(text=>text.remove());document.querySelectorAll('[data-event-edit]').forEach(button=>{button.textContent='Editar evento';if(!button.parentElement.querySelector('[data-event-photos]'))button.insertAdjacentHTML('afterend','<button class="secondary" data-event-photos="'+button.dataset.eventEdit+'">Editar fotos</button>')})};
function photoEditor(eventId){api('/api/team/events').then(data=>{const event=(data.events||[]).find(x=>x.id===eventId);if(!event)return notify('Evento não encontrado.');const photos=event.photos||[];const previews=photos.map((p,i)=>{const photo=typeof p==='string'?{watermarked:p,original:p,price:0}:p;return '<label class="photo-edit-row"><input type="checkbox" name="keep'+i+'" checked><img src="'+esc(photo.watermarked||photo.original||'#')+'" alt="Foto '+(i+1)+'"><span>Foto '+(i+1)+'</span></label>'}).join('');openModal('Editar fotos do evento','<p class="muted">Desmarque uma foto para apagar. O preço informado será aplicado a todas as fotos mantidas e novas.</p><div class="photo-editor-grid">'+(previews||'<p class="muted">Nenhuma foto cadastrada.</p>')+'</div><label class="field">Preço de todas as fotos<input required name="photoPrice" type="number" min="0" step="0.01" value="'+esc(photos[0]?.price??'')+'"></label><label class="field">Adicionar fotos<input type="file" name="photos" accept="image/*" multiple></label>','Salvar fotos',async d=>{try{const price=Number(d.get('photoPrice')||0),kept=photos.filter((_,i)=>d.get('keep'+i)==='on').map(p=>typeof p==='string'?{watermarked:p,original:p,price}:({...p,price})),files=d.getAll('photos').filter(f=>f?.size),added=await Promise.all(files.map(async file=>({...await watermarkPhoto(file),price})));await api('/api/team/events/'+eventId,{method:'PATCH',body:JSON.stringify({photos:[...kept,...added]})});$('modal').close();eventsAreaView();loadPublicEvents();notify('Fotos atualizadas.')}catch(err){notify(err.message)}return false})}).catch(err=>notify(err.message))}
document.addEventListener('click',e=>{const photoButton=e.target.closest('[data-event-photos]');if(photoButton){photoEditor(photoButton.dataset.eventPhotos);return}const toggle=e.target.closest('[data-toggle-photos]');if(toggle){const gallery=document.querySelector('[data-photos-for="'+toggle.dataset.togglePhotos+'"]');if(gallery)toggle.textContent=gallery.hidden?'Ver fotos ('+gallery.querySelectorAll('.photo-sale').length+')':'Não ver fotos';return}});
